    ["02-10"] = {steps={[1]={npc="Бацбах Кривошип", tgt="Бацбах Кривошип"}, [2]={npc="Гвеннид Блай'Леггонд", tgt="Гвеннид Блай'Леггонд"}, [3]={node="Аубердин"}, [4]={hint="Добудьте 6 ножек крабов и поместите их в Жужжалку 827."}, [5]={hint="Соберите кости морской твари, выброшенной на берег к югу от Аубердина, и принесите их Гвеннид Блай'Леггонд в Аубердин."}, [6]={npc="Жужжалка 827", npcObj=true}, [7]={npc="Жужжалка 827", npcObj=true}, [8]={npc="Гвеннид Блай'Леггонд", tgt="Гвеннид Блай'Леггонд"}, [9]={npc="Гвеннид Блай'Леггонд", tgt="Гвеннид Блай'Леггонд"}, [10]={hint="Принесите 8 партий элунитовой руды и медальон Элуры Эланарии из Дарнасса."}, [11]={npc="Кириллиан Белый Коготь", tgt="Кириллиан Белый Коготь"}, [12]={hint="Извлеките останки морской черепахи из скелета морской черепахи, лежащего в воде к западу от Аубердина, а затем поговорите с Гвеннид Блай'Леггонд в Аубердине."}, [13]={hint="Добудьте 3 глаза крепкозуба с крепкозубов Темного Берега, которые водятся в море неподалеку от Жужжалки 411."}, [14]={text="Бегите по дороге до этой точки."}, [15]={npc="Тандрис Ветропряд", tgt="Тандрис Ветропряд"}, [16]={npc="Тандрис Ветропряд", tgt="Тандрис Ветропряд"}, [17]={npc="Тарнариун Исцелитель Деревьев", tgt="Тарнариун Исцелитель Деревьев"}, [18]={npc="Терентис", tgt="Терентис"}, [19]={text="Бегите по дороге до этой точки."}, [20]={hint="Поймайте бешеного колючешерстного медведя отведите его Тарнариуну."}, [21]={hint="Посыпьте лунной пылью Кенария камень лунного совуха в Аубердине, чтобы вызвать Лунокогтя. Победите Лунокогтя, чтобы получить силу его тела и духа."}, [22]={npc="Астерион", tgt="Астерион"}, [23]={npc="Астерион", tgt="Астерион"}, [24]={hint="Соберите 8 серег греллей для Астериона в Башал'Аране."}, [25]={npc="Астерион", tgt="Астерион"}, [26]={npc="Астерион", tgt="Астерион"}, [27]={hint="Добудьте древнюю печать из лунного камня и принесите ее Астериону в Башал'Аран."}, [28]={npc="Астерион", tgt="Астерион"}, [29]={npc="Астерион", tgt="Астерион"}, [30]={npc="Т