    ["02-11"] = {steps={[1]={node="Stormwind"}, [2]={text="Выйдите из Штормграда и идите на запад по дороге через Элвиннский лес, пройдите через Златоземье и по мосту попадите в Западный Край, а затем по большой дороге идите на юг до Сторожевого холма.", tag="Маршрут полёта ещё не открыт. В первый раз доберитесь туда пешком."}, [3]={npc="Заместитель судьи Рейнер", tgt="Заместитель судьи Рейнер"}, [4]={npc="Фермер Хмуробров", tgt="Фермер Хмуробров"}, [5]={npc="Верна Хмуробров", tgt="Верна Хмуробров"}, [6]={npc="Верна Хмуробров", tgt="Верна Хмуробров"}, [7]={hint="Принесите 8 горстей овса Верне Хмуробров.", tag="Необязательно"}, [8]={npc="Фермер Сальден", tgt="Фермер Сальден"}, [9]={npc="Сальма Сальден", tgt="Сальма Сальден"}, [10]={npc="Озвин Железнозубчик", tgt="Озвин Железнозубчик"}, [11]={npc="Гриан Камнегрив", tgt="Гриан Камнегрив"}, [12]={npc="Гриан Камнегрив", tgt="Гриан Камнегрив"}, [13]={nodeA="{a:108}"}, [14]={npc="Разведчик Галиан", tgt="Разведчик Галиан"}, [15]={npc="Альба Светлая Луна", tgt="Альба Светлая Луна"}, [16]={npc="Альба Светлая Луна", tgt="Альба Светлая Луна"}, [17]={hint="Используйте набор для взятия образцов колодезной воды у колодцев во владении Янсена и на ферме Мольсена."}, [18]={hint="Верните фермеру Хмуроброву его карманные часы, которые находятся в платяном шкафу в его доме на тыквенной ферме на западе.", desc="Поверните камеру — подобрать можно снаружи."}, [19]={hint="Альба Светлая Луна просит раздобыть 7 жабр мурлоков с Бескрайнего берега на побережье Западного края."}, [20]={npc="Фермер Хмуробров", tgt="Фермер Хмуробров"}, [21]={hint="Убейте 20 дозорных полей по просьбе фермера Сальдена."}, [22]={npc="Верна Хмуробров", tgt="Верна Хмуробров"}, [23]={npc="Фермер Сальден", tgt="Фермер Сальден"}, [24]={npc="Альба Светлая Луна", tgt="Альба Светлая Луна"}, [25]={npc="Альба Светлая Луна", tgt="Альба Светлая Луна"}, [26]={npc="Альба Светлая Луна", tgt="Альба Светлая Луна"}, [27]={hint="Убейте 4 кобольдов-землекопов на руднике Янго и 6 шахтеро