    ["05-d1"] = {name="Чертоги танов", entrance="Стальгорн 27.63, 47.83", pickup="Проходя через Дун Морог и Лок Модан, сначала возьмите задания перед подземельем; специально возвращаться перед входом не нужно. Скайборны пропускают 01-этап 9: при первом визите в Стальгорн идите на восток в Дун Морог к Землевидцу Фарсену, выполните «Дозор Фарсена», «Подавить в зародыше» и «Карта подземелий» и вернитесь в Стальгорн. Если не хотите делать крюк, пропустите «Вторжение в Старый Стальгорн».", pickupS={{"Проходя через Дун Морог и Лок Модан, сначала возьмите задания перед подземельем; специально возвращаться перед входом не нужно"}, {"Скайборны пропускают 01-этап 9: при первом визите в Стальгорн идите на восток в Дун Морог к Землевидцу Фарсену, выполните «Дозор Фарсена», «Подавить в зародыше» и «Карта подземелий» и вернитесь в Стальгорн", {race={"天裔"}}}, {"Если не хотите делать крюк, пропустите «Вторжение в Старый Стальгорн»"}}, steps={[1]={npc="Карта клана Черного Железа", npcObj=true, tag="Подготовка к подземелью"}, [2]={npc="Землевидец Фарсен", tgt="Землевидец Фарсен", tag="Подготовка к подземелью"}, [3]={npc="Землевидец Фарсен", tgt="Землевидец Фарсен"}, [4]={npc="Афадра Серостен", tgt="Афадра Серостен"}, [5]={npc="Том Стаск", tgt="Том Стаск"}, [6]={npc="Ghostly Attendant", tgt="Ghostly Attendant"}, [7]={text="Вход: Чертоги танов"}, [8]={npc="Ghostly Attendant", tgt="Ghostly Attendant"}, [9]={hint="Убейте 15 |4разъяренную тень:разъяренные тени:разъяренных теней;, 10 |4замученную душу:замученные души:замученных душ; даруйте покой духу Старой Наковальни."}, [10]={hint="Добудьте 8 |4дворфийскую реликвию:дворфийские реликвии:дворфийских реликвий; в Чертогах танов."}, [11]={hint="Войдите в Чертоги танов под Старым Стальгорном и добудьте голову Даргена Сокрушающий Молот."}, [12]={npc="Treaty of Understanding", npcObj=true, desc="Последний босс накладывает страх примерно на 35% здоровья. Сначала зачистите мелочь, затем отведите босса в предыдущую комнату. Рядом с тем, кто выдает