    ["02-12"] = {steps={[1]={npc="Грит Турден", tgt="Грит Турден"}, [2]={node="Стальгорн"}, [4]={text="Выйдите из Стальгорна и идите на восток по большой дороге, пройдите через туннель в восточном перевале в Лок Модан, а затем по дороге на северо-восток дойдите до Телсамара.", tag="Маршрут полёта ещё не открыт. В первый раз доберитесь туда пешком."}, [5]={nodeA="{a:144}"}, [6]={hint="Горный пехотинец Булыжный Карьер просит вас убить 10 головоломов из племени Камнедробов и 10 ясновидцев из племени Камнедробов."}, [7]={npc="Горный пехотинец Булыжный Карьер", tgt="Горный пехотинец Булыжный Карьер"}, [8]={npc="Горный пехотинец Стенолом", tgt="Горный пехотинец Стенолом"}, [9]={hint="Возьмите знак Жизни и воскресите Нарма Фолка в Дун Мороге."}, [10]={npc="Джерн Шлеморог", tgt="Джерн Шлеморог"}, [11]={npc="Брок Камнекоп", tgt="Брок Камнекоп"}, [12]={npc="Магмар Рудокол", tgt="Магмар Рудокол"}, [13]={npc="Магмар Рудокол", tgt="Магмар Рудокол"}, [14]={npc="Геолог Сталекрут", tgt="Геолог Сталекрут"}, [15]={npc="Дэрил Юный", tgt="Дэрил Юный"}, [16]={hint="Убейте 6 горных канюков и вернитесь к Дэрилу Юному в Приют странников. На выполнение задания отводится 15 минут."}, [17]={npc="Дэрил Юный", tgt="Дэрил Юный"}, [18]={npc="Дэрил Юный", tgt="Дэрил Юный"}, [19]={hint="Убейте 5 старых горных вепрей и вернитесь к Дэрилу Юному в Приют странников. На выполнение задания отводится 12 минут."}, [20]={npc="Дэрил Юный", tgt="Дэрил Юный"}, [21]={npc="Марек Железносерд", tgt="Марек Железносерд"}, [22]={npc="Марек Железносерд", tgt="Марек Железносерд"}, [23]={npc="Бинглз Покрышкинс", tgt="Бинглз Покрышкинс"}, [24]={npc="Бинглз Покрышкинс", tgt="Бинглз Покрышкинс"}, [25]={hint="Найдите и победите кроколиска Ножезуба и верните Мареку его нож."}, [26]={hint="Принесите Мареку Железносерду в Приют Странников 5 кусков мяса кроколиска и 6 шкур кроколиска."}, [27]={hint="Найдите и верните Бинглзу гаечный ключ Бинглза, отвертку Бинглза, молот Бинглза и сорвиголовку Бинглза."}, [28]={hint="Горный пехо