к медведя."}, [56]={npc="Матренгил Медвежья Лапа", tgt="Матренгил Медвежья Лапа"}, [57]={npc="Дендрит Блеск Звезд", tgt="Дендрит Блеск Звезд"}, [58]={npc="Дендрит Блеск Звезд", tgt="Дендрит Блеск Звезд"}, [59]={hint="Используйте пустую колбу для взятия пробы воды из устья пещеры у водопада Скалистый.", desc="Слетайте из Ночной Гавани на рейсе только для друидов в Деревню Рут'теран, а оттуда летите в Аубердин."}, [60]={npc="Аландариан Песня Ночи", tgt="Аландариан Песня Ночи"}, [61]={npc="Аландариан Песня Ночи", tgt="Аландариан Песня Ночи", desc="Соберите землекорень и лунные грибы на Темных берегах и сдайте в Аубердине."}, [62]={hint="Принесите 5 корешков землекорня и 12 лунных грибов Аландариан Песне Ночи в Аубердине, чтобы она могла сделать целительную мазь.", desc="Соберите землекорень и лунные грибы на Темных берегах и сдайте в Аубердине."}, [63]={npc="Аландариан Песня Ночи", tgt="Аландариан Песня Ночи", desc="Соберите землекорень и лунные грибы на Темных берегах и сдайте в Аубердине."}, [64]={npc="Аландариан Песня Ночи", tgt="Аландариан Песня Ночи", desc="Вылечите больных оленей на Темных берегах с помощью лекарства."}, [65]={hint="Нанесите мазь исцеления животных на 10 больных оленей, обитающих на Темном Берегу, - это должно их исцелить. По слухам, ареал обитания больных оленей - южнее реки Скалистой и севернее Аубердина, а далее - по всей области, вплоть до южных границ Темного Берега, где начинается Ясеневый лес.", desc="Вылечите больных оленей на Темных берегах с помощью лекарства."}, [66]={npc="Дендрит Блеск Звезд", tgt="Дендрит Блеск Звезд", desc="Вылечив 10 оленей, используйте «Телепортация: Лунная поляна», чтобы вернуться и сдать задание."}, [67]={npc="Дендрит Блеск Звезд", tgt="Дендрит Блеск Звезд", desc="Сдайте задание, чтобы изучить «Излечение от яда»."}, [68]={npc="Матренгил Медвежья Лапа", tgt="Матренгил Медвежья Лапа", desc="Сдайте задание и выучите «Излечение от яда». Слетайте из Ночной Гавани на рейсе только для друидов в Деревню Рут'теран и войдите в Дарнас через портал в деревне."}, [69]={npc="Матренгил Медвежья Лапа", tgt="Матренгил Медвежья Лапа"}, [70]={npc="Дендрит Блеск Звезд", tgt="Дендрит Блеск Звезд"}, [71]={npc="Дендрит Блеск Звезд", tgt="Дендрит Блеск Звезд", desc="Найдите безделушку из святилища на дне озера Элуны."}, [72]={hint="Найдите безделушку святилища в озере Элуны и отнесите ее в святилище Ремулоса на северо-западе Лунной Поляны. Оказавшись там, воспользуйтесь безделушкой.", desc="Найдите безделушку из святилища на дне озера Элуны."}, [73]={npc="Таджарри", tgt="Таджарри", desc="Найдите безделушку из святилища на дне озера Элуны."}, [74]={npc="Таджарри", tgt="Таджарри", desc="В двух странных запертых сундуках лежит по половине подвески: один на морском дне к северу от Аубердина на Темных берегах, другой на морском дне у северо-западного берега Западного Края."}, [75]={hint="Найдите половинку подвески Ловкости водяного облика и половинку подвески Выносливости водяного облика. Поговорите с жителями Лунной поляны, чтобы узнать, где могут находиться эти предметы.", desc="Слетайте из Ночной Гавани на рейсе только для друидов в Деревню Рут'теран, летите в Аубердин и плывите на север к запертому сундуку на морском дне. Затем плывите на корабле из Аубердина в Штормград, летите на Сторожевой холм и идите на северо-запад к берегу, чтобы нырнуть и открыть другой запертый сундук."}, [76]={text="Собрав обе половины, используйте «Телепортация: Лунная поляна», вернитесь и соедините половины подвески у Святилища Ремулоса."}, [77]={npc="Дендрит Блеск Звезд", tgt="Дендрит Блеск Звезд"}, [78]={npc="Дендрит Блеск Звезд", tgt="Дендрит Блеск Звезд", desc="Сдайте задание, чтобы изучить «Водный облик»."}, [79]={npc="Матренгил Медвежья Лапа", tgt="Матренгил Медвежья Лапа", desc="Сдайте задание и выучите «Водный облик». Слетайте из Ночной Гавани на рейсе только для друидов в Деревню Рут'теран и войдите в Дарнас через портал в деревне."}}},
    ["02-13"] = {steps={[1]={npc="Груббер Блумп", tgt="Груббер Блумп"}, [2]={npc="Розыск: Глубомрак!", npcObj=true}, [3]={npc="Археолог Холли", tgt="Археолог Холли"}, [4]={npc="Археолог Холли", tgt="Археолог Холли"}, [5]={npc="Тандрис Ветропряд", tgt="Тандрис Ветропряд"}, [6]={npc="Горбольд Сталерук", tgt="Горбольд Сталерук"}, [7]={npc="Горбольд Сталерук", tgt="Горбольд Сталерук"}, [8]={npc="Гершал Шепот Ночи", tgt="Гершал Шепот Ночи"}, [9]={npc="Терентис", tgt="Терентис"}, [10]={npc="Терентис", tgt="Терентис"}, [11]={npc="Таинственный красный кристалл", npcObj=true}, [12]={npc="Таинственный красный кристалл", npcObj=true}, [13]={npc="Астерион", tgt="Астерион"}, [14]={npc="Выброшенная на берег морская тварь", npcObj=true}, [15]={hint="Добудьте денежный ящик \"Серебряной Зари\" и денежный ящик \"Туманной Пелены\" для Горбольда Стальная Рука в Аубердине. Оба предмета можно найти в останках потерпевших крушение кораблей к северу от деревни."}, [16]={npc="Жужжалка 411", npcObj=true}, [17]={npc="Жужжалка 411", npcObj=true}, [18]={npc="Выброшенная на берег морская черепаха", npcObj=true}, [19]={text="Бегите по дороге до этой точки.", desc="Дальше по пути бейте всех малорослых лунопардов и бешеных колючешерстных медведей."}, [20]={text="Бегите по дороге до этой точки."}, [21]={hint="Отправляйтесь на север от Аубердина, к первому водопаду вверх по реке Скалистой, и там возьмите пробу."}, [22]={hint="Соберите 6 кусочков отличного крабьего мяса для Груббера Блумпа в Аубердине."}, [23]={npc="Выброшенная на берег морская черепаха", npcObj=true}, [24]={npc="Балтул Удар Тени", tgt="Балтул Удар Тени"}, [25]={npc="Балтул Удар Тени", tgt="Балтул Удар Тени"}, [26]={hint="Соберите 4 свитка истрепанного пергамента для Балтула Удара Тени возле башни Алталакса."}, [27]={npc="Балтул Удар Тени", tgt="Балтул Удар Тени"}, [28]={npc="Балтул Удар Тени", tgt="Балтул Удар Тени"}, [29]={hint="Очистите лес от 20 бешеных колючешерстных медведей и возвращайтесь к Тарнариуну Исцелителю Деревьев на Темный Берег."}, [30]={hint="Добудьте 6 клыков лунупарда и поместите их в Жужжалку 323."}, [31]={hint="Принесите 5 ножек струпника и 1 мертвянку Баритасу Лунному Сумраку в Аубердин."}, [32]={npc="Жужжалка 323", npcObj=true}, [33]={npc="Жужжалка 323", npcObj=true}, [34]={npc="Тарнариун Исцелитель Деревьев", tgt="Тарнариун Исцелитель Деревьев"}, [35]={npc="Тарнариун Исцелитель Деревьев", tgt="Тарнариун Исцелитель Деревьев"}, [36]={npc="Горбольд Сталерук", tgt="Горбольд Сталерук"}, [37]={npc="Тандрис Ветропряд", tgt="Тандрис Ветропряд"}, [38]={npc="Тандрис Ветропряд", tgt="Тандрис Ветропряд"}, [39]={npc="Часовой Глинда Нал'Шия", tgt="Часовой Глинда Нал'Шия"}, [40]={npc="Баритас Лунный Сумрак", tgt="Баритас Лунный Сумрак", desc="Наполните пустую чашу Очищения у лунного колодца."}, [41]={npc="Баритас Лунный Сумрак", tgt="Баритас Лунный Сумрак"}, [42]={npc="Гвеннид Блай'Леггонд", tgt="Гвеннид Блай'Леггонд"}, [43]={npc="Гвеннид Блай'Леггонд", tgt="Гвеннид Блай'Леггонд"}, [44]={npc="Гвеннид Блай'Леггонд", tgt="Гвеннид Блай'Леггонд"}, [45]={npc="Груббер Блумп", tgt="Груббер Блумп"}, [46]={npc="Выброшенная на берег морская тварь", npcObj=true}, [47]={npc="Выброшенная на берег морская тварь", npcObj=true, desc="Событие начинается только рядом с костром. Сделайте сейчас или позже, когда маршрут снова пройдет мимо."}, [48]={npc="Выброшенная на берег морская черепаха", npcObj=true}, [49]={npc="Выброшенная на берег морская черепаха", npcObj=true}, [50]={npc="Выброшенная на берег морская тварь", npcObj=true}, [51]={text="Бегите по дороге до этой точки."}, [52]={npc="Часовой Айнаша", tgt="Часовой Айнаша", desc="По пути к следующему заданию бейте взрослых лунопардов (детеныши и матриарх подтянутся вместе с ними)."}, [53]={hint="Защитите жизнь часового Айнаши, а потом поговорите с Ойнеей на Заставе Мейстры в Ясеневом лесу."}, [54]={npc="Ону", tgt="Ону"}, [55]={npc="Ону", tgt="Ону"}, [56]={npc="Гадальная чаша", npcObj=true, desc="Идите к 39.2, 86.9 и используйте флакон от Ону, чтобы поставить его на землю."}, [57]={npc="Гадальная чаша", npcObj=true}, [58]={npc="Сумеречный фолиант", npcObj=true}, [59]={npc="Сумеречный фолиант", npcObj=true}, [60]={npc="Сумеречный фолиант", npcObj=true}, [61]={hint="Добудьте несравненное око у сумеречного послушника или сумеречного лиходея у Меча Властителя на Темных берегах и найдите в Аубердине того, кто заберет его у вас."}, [62]={npc="Тирелин", tgt="Тирелин", desc="Задание на сопровождение: в группе берите, когда у всех одинаковый прогресс, и отключите автопринятие."}, [63]={hint="Помогите Тирелин спастись, а потом сообщите Тересиль у святилища Эссины, что ее сестра в безопасности."}, [64]={npc="Книга Подземные Силы", npcObj=true, tag="Необязательно", desc="Щелкните правой кнопкой по предмету «Книга \"Подземные Силы\"» в сумке, чтобы взять задание. Монстры в яме изредка роняют «Книга \"Подземные Силы\"». Берите задание, только если выпадет."}, [65]={npc="Геолог Сомнамбулер", tgt="Геолог Сомнамбулер", desc="Задание на сопровождение: в группе берите, когда у всех одинаковый прогресс, и отключите автопринятие. Пусть геолог Сомнамбулер бежит первым, атакуйте только тех, кто нападает на него."}, [66]={npc="Геолог Сомнамбулер", tgt="Геолог Сомнамбулер"}, [67]={hint="Защищайте геолога Сомнамбулера, пока он ищет таинственную окаменелость, а затем вернитесь к археологу Холли в Аубердин."}, [68]={npc="Жужжалка 525", npcObj=true}, [69]={hint="Найдите 5 прекрасных шкур лунопарда и принесите их Терентису в Аубердин."}, [70]={npc="Ону", tgt="Ону"}, [71]={npc="Арбал", tgt="Арбал"}, [72]={npc="Ону", tgt="Ону"}, [73]={hint="Найдите и убейте мурлока, известного как Глубомрак. Предполагается, что это существо охраняет и защищает хижины мурлоков в поселении к югу от Аубердина, у воды.", desc="Придет несколько волн мурлоков, по 2-3 в каждой. Последнего мурлока каждой волны уводите от костра и только потом убивайте, поешьте и попейте, затем зовите следующую волну. Или найдите группу."}, [74]={npc="Гвеннид Блай'Леггонд", tgt="Гвеннид Блай'Леггонд"}, [75]={npc="Гвеннид Блай'Леггонд", tgt="Гвеннид Блай'Леггонд"}, [76]={npc="Гвеннид Блай'Леггонд", tgt="Гвеннид Блай'Леггонд"}, [77]={npc="Гвеннид Блай'Леггонд", tgt="Гвеннид Блай'Леггонд"}, [78]={npc="Гвеннид Блай'Леггонд", tgt="Гвеннид Блай'Леггонд"}, [79]={npc="Гвеннид Блай'Леггонд", tgt="Гвеннид Блай'Леггонд"}, [80]={npc="Часовой Глинда Нал'Шия", tgt="Часовой Глинда Нал'Шия"}, [81]={npc="Археолог Холли", tgt="Археолог Холли"}, [82]={npc="Археолог Холли", tgt="Археолог Холли"}, [83]={npc="Тандрис Ветропряд", tgt="Тандрис Ветропряд"}, [84]={npc="Терентис", tgt="Терентис"}, [85]={npc="Терентис", tgt="Терентис"}, [87]={desc="Если Деревни Рут'теран нет на карте полётов, плывите на корабле, как остальные расы."}, [88]={npc="Несса Песня Теней", tgt="Несса Песня Теней"}, [89]={text="Пройдите через портал в Деревне Рут'теран в Дарнас."}, [90]={npc="Главный археолог Седоус", tgt="Главный археолог Седоус"}, [91]={npc="Главный археолог Седоус", tgt="Главный археолог Седоус"}, [92]={text="Пройдите через портал в Дарнасе обратно в Деревню Рут'теран."}, [93]={nodeA="{a:702}"}, [95]={hint="Найдите и убейте мать-медведицу."}, [96]={hint="Наполните пустую чашу очищения из лунного колодца Аубердина."}, [97]={hint="Принесите Ону в Рощу Древних 6 реликвий Матистры."}, [98]={hint="Убейте 12 |4мирмидона:мирмидонов:мирмидонов;, 8 |4колдунью:колдуний:колдуний; и 6 |4воина:воинов:воинов; из клана Гремучей чешуи по просьбе Арбала из Рощи Древних."}, [99]={hint="Найдите укротительницу из клана Гремучей Чешуи, убейте ее и добудьте жезл беспредельной власти."}, [100]={npc="Renzik The Shiv", tgt="Renzik The Shiv"}, [101]={text="Если Приозерье можно выбрать, летите; иначе выйдите из Штормграда по Элвиннской дороге на восток в Красногорье и по пути в Приозерье откройте пункт полета."}, [102]={npc="Люций", tgt="Люций"}, [103]={npc="Люций", tgt="Люций", desc="Примените Взлом замка к сундуку у Лесопилки Алтера."}, [104]={hint="Откройте сундук Люция, достаньте Руну Воровства и вернитесь к Люцию в Приозерье.", desc="Примените Взлом замка к сундуку у Лесопилки Алтера."}, [105]={npc="Люций", tgt="Люций", desc="Примените Взлом замка к сундуку у Лесопилки Алтера."}, [106]={npc="Арантир", tgt="Арантир", tag="Необязательно"}, [107]={hint="Верните рога Незры Арантиру в Приозерье.", tag="Необязательно"}, [108]={npc="Арантир", tgt="Арантир", tag="Необязательно"}, [109]={npc="Мастер Матиас Шоу", tgt="Мастер Матиас Шоу"}, [110]={npc="Посланница Кеарнен", tgt="Посланница Кеарнен"}, [111]={npc="Посланница Кеарнен", tgt="Посланница Кеарнен", desc="Украдите запечатанное письмо из башни Братства Справедливости в Западном Крае. Затем изучите «Яды»."}, [112]={hint="Добудьте ключ Башни Братства Справедливости, проберитесь в башню и выясните, каково содержимое сундука из Сумеречного леса. Отнесите найденные вещи Матиасу Шоу в Штормград. Почитайте дневник Кеарнен, чтобы больше узнать о башне.", desc="Украдите запечатанное письмо из башни Братства Справедливости в Западном Крае. Затем изучите «Яды»."}, [113]={npc="Мастер Матиас Шоу", tgt="Мастер Матиас Шоу", desc="Украдите запечатанное письмо из башни Братства Справедливости в Западном Крае. Затем изучите «Яды»."}, [114]={npc="Мастер Матиас Шоу", tgt="Мастер Матиас Шоу", tag="Необязательно"}, [115]={npc="Док Миксиль-Пиксиль", tgt="Док Миксиль-Пиксиль", tag="Необязательно"}, [116]={npc="Док Миксиль-Пиксиль", tgt="Док Миксиль-Пиксиль", tag="Необязательно"}, [117]={npc="Док Миксиль-Пиксиль", tgt="Док Миксиль-Пиксиль", tag="Необязательно"}, [118]={npc="Док Миксиль-Пиксиль", tgt="Док Миксиль-Пиксиль", tag="Необязательно"}, [119]={hint="Принесите Доку Миксиль-Пиксилю один букетик простых полевых цветов, одну освинцованную колбу, одну бронзовую трубку и одну катушку светлого зеленовато-желтого шелка. Чтотит, знаете ли, сам собой не проходит.", tag="Необязательно"}, [120]={npc="Док Миксиль-Пиксиль", tgt="Док Миксиль-Пиксиль", tag="Необязательно"}, [121]={npc="Верховная жрица Лорена", tgt="Верховная жрица Лорена", desc="Изучите «Обратная связь»."}, [122]={npc="Верховная жрица Лорена", tgt="Верховная жрица Лорена", desc="Изучите «Обратная связь»."}, [123]={npc="Верховная жрица Лорена", tgt="Верховная жрица Лорена", desc="Возьмите в Штормграде, сдайте в Стальгорне и изучите «Защиту от страха»."}, [124]={npc="Верховный жрец Рохан", tgt="Верховный жрец Рохан", desc="Возьмите в Штормграде, сдайте в Стальгорне и изучите «Защиту от страха»."}, [125]={npc="Верховная жрица Лорена", tgt="Верховная жрица Лорена", desc="Возьмите в Штормграде и сдайте в Дун Мороге."}, [126]={npc="Верховная жрица Мимс", tgt="Верховная жрица Мимс", desc="Возьмите в Штормграде и сдайте в Дун Мороге."}, [127]={npc="Джинния Пушка", tgt="Джинния Пушка", desc="Таверна «Синий Отшельник» находится в квартале магов Штормграда."}, [128]={hint="Возьмите свиток заклинания Проявления и ящик с шкатулками-духоловками за спиной у Джиннии Пушки. Принесите 3 заполненных шкатулки-духоловки Джиннии в Башню магов.", desc="Таверна «Синий Отшельник» находится в квартале магов Штормграда."}, [129]={npc="Джинния Пушка", tgt="Джинния Пушка", desc="Таверна «Синий Отшельник» находится в квартале магов Штормграда."}, [130]={npc="Джинния Пушка", tgt="Джинния Пушка", desc="Сдайте 10 льняного материала и 6 заряженных самоцветов Расселины. Самоцветы можно купить на аукционе."}, [131]={npc="Уинн Ларсон", tgt="Уинн Ларсон", desc="Сдайте 10 льняного материала и 6 заряженных самоцветов Расселины. Самоцветы можно купить на аукционе."}, [132]={npc="Уинн Ларсон", tgt="Уинн Ларсон", desc="Награда: одеяние из ткани маны."}, [133]={npc="Уинн Ларсон", tgt="Уинн Ларсон", desc="Награда: одеяние из ткани маны."}, [134]={npc="Гакин Темнопряд", tgt="Гакин Темнопряд"}, [135]={npc="Такар Провидец", tgt="Такар Провидец", desc="Сядьте в порту Штормграда на корабль до Аубердина, идите вдоль побережья Темных берегов на юг в Ясеневый лес, затем с востока через Бастион Мор'шан войдите в Степи и идите на юг искать Такара Провидца. Перекресток и Лагерь Таурахо - опорные пункты Орды; обходите их."}, [136]={npc="Такар Провидец", tgt="Такар Провидец"}, [137]={npc="Такар Провидец", tgt="Такар Провидец"}, [138]={hint="Раздобудьте в Ясеневом лесу сердцедрево и принесите его Гакину Темнопряду в Квартал магов Штормграда.", desc="Сначала перебейте монстров у дерева, затем щелкните по древу Кенария, чтобы получить сердцедрево."}, [139]={hint="Добудьте деревянную статуэтку и принесите ее Гакину Темнопряду в квартал магов Штормграда."}, [140]={npc="Гакин Темнопряд", tgt="Гакин Темнопряд", desc="Закончив в Ясеневом лесу, вернитесь камнем возвращения в Штормград. Если камень возвращения на перезарядке, вернитесь на север в Аубердин и сядьте на корабль до Штормграда."}, [141]={npc="Гакин Темнопряд", tgt="Гакин Темнопряд"}, [142]={npc="Гакин Темнопряд", tgt="Гакин Темнопряд", desc="Используйте у круга призыва рядом с Гакином Темнопрядом и победите призванного суккуба."}, [143]={hint="Призовите и подчините суккуба, используя сердцевину сердцедрева, затем верните сердцевину сердцедрева Гакину Темнопряду. Он будет ждать вас в \"Забитом ягненке\".", desc="Используйте у круга призыва рядом с Гакином Темнопрядом и победите призванного суккуба."}, [144]={npc="Гакин Темнопряд", tgt="Гакин Темнопряд", desc="Используйте у круга призыва рядом с Гакином Темнопрядом и победите призванного суккуба."}, [145]={npc="Гакин Темнопряд", tgt="Гакин Темнопряд"}, [146]={hint="Воспользуйтесь деревянной статуэткой, чтобы призвать и подчинить инкуба, затем верните статуэтку Гакину Темнопряду. Он будет ждать в \"Забитом ягненке\"."}, [147]={npc="Гакин Темнопряд", tgt="Гакин Темнопряд"}, [148]={}}},
    ["05-d2"] = {name="Руины Лордерона", entrance="Подгород 72.41, 11.37", steps={[1]={text="Необязательное и далекое: вход находится в Руинах Лордерона над Подгородом, поэтому придется пройти по территории Орды. Сядьте в Аубердине на корабль до Гавани Менетилов, сойдите в Южнобережье и откройте точку полета, затем идите на север через Предгорья Хилсбрада и Серебряный бор в Тирисфальские леса. После подземелья вернитесь камнем возвращения в Штормград и продолжайте с 02-этап 14.", tag="Необязательно, Требуется внутриигровая проверка"}, [2]={}, [3]={npc="Окровавленный знак отличия", npcObj=true, desc="Щелкните правой кнопкой по предмету «Окровавленный знак отличия» в сумке, чтобы взять задание."}, [4]={text="Вход: Руины Лордерона"}, [5]={hint="Соберите 10 |4окровавленный знак:окровавленных знака:окровавленных знаков; отличия и принесите их генералу Маркусу Джонатану."}, [6]={npc="Герб Лордерона", npcObj=true, desc="Щелкните правой кнопкой по предмету «Герб Лордерона» в сумке, чтобы взять задание."}, [7]={npc="Blood-Stained Parchment", npcObj=true}, [8]={}, [9]={npc="Попечительница сирот Найтингейл", tgt="Попечительница сирот Найтингейл"}, [10]={npc="Леди Дена Кеннеди", tgt="Леди Дена Кеннеди"}, [11]={npc="Генерал Маркус Джонатан", tgt="Генерал Маркус Джонатан"}}},
    ["02-14"] = {steps={[1]={text="От Штормграда идите на восток по дороге через Элвиннский лес в Красногорье и по большой дороге дойдите до Приозерья.", tag="Маршрут полёта ещё не открыт. В первый раз доберитесь туда пешком."}, [2]={npc="Теокрит", tgt="Теокрит"}, [3]={npc="Стражник Паркер", tgt="Стражник Паркер"}, [4]={}, [5]={npc="Стражник Паркер", tgt="Стражник Паркер", desc="Стражник Паркер стоит на развилке главной дороги к западу от Красногорья, ведущей в Элвиннском лесу."}, [6]={npc="Дарси", tgt="Дарси"}, [7]={npc="Вилли Черный", tgt="Вилли Черный"}, [8]={npc="Вилли Черный", tgt="Вилли Черный"}, [9]={npc="Портовый начальник Барен", tgt="Портовый начальник Барен"}, [10]={npc="Портовый начальник Барен", tgt="Портовый начальник Барен"}, [11]={npc="Мировой судья Соломон", tgt="Мировой судья Соломон"}, [12]={npc="Вернер Осгуд", tgt="Вернер Осгуд"}, [13]={npc="Заместитель судьи Фелдон", tgt="Заместитель судьи Фелдон"}, [14]={npc="Заместитель судьи Фелдон", tgt="Заместитель судьи Фелдон"}, [15]={npc="Заместитель судьи Фелдон", tgt="Заместитель судьи Фелдон"}, [16]={nodeA="{a:69}"}, [18]={npc="Гриан Камнегрив", tgt="Гриан Камнегрив"}, [19]={npc="Гриан Камнегрив", tgt="Гриан Камнегрив"}, [21]={npc="Генерал Маркус Джонатан", tgt="Генерал Маркус Джонатан"}, [22]={npc="Генерал Маркус Джонатан", tgt="Генерал Маркус Джонатан"}, [23]={npc="Кузнец Аргус", tgt="Кузнец Аргус"}, [24]={npc="Кузнец Аргус", tgt="Кузнец Аргус"}, [25]={npc="Мастер Матиас Шоу", tgt="Мастер Матиас Шоу"}, [26]={npc="Мастер Матиас Шоу", tgt="Мастер Матиас Шоу"}, [28]={npc="Гриан Камнегрив", tgt="Гриан Камнегрив"}, [29]={npc="Гриан Камнегрив", tgt="Гриан Камнегрив"}, [30]={hint="Выследите вестника из Братства Справедливости в Западном Крае и принесите отнятое у него сообщение Гриану Камнегриву."}, [31]={npc="Гриан Камнегрив", tgt="Гриан Камнегрив"}, [32]={npc="Предатель Братства Справедливости", tgt="Предатель Братства Справедливости"}, [33]={hint="Сопроводите предателя к тайному убежищу Братства Справедливости. Когда он покажет, где прячутся ван Клиф и его люди, вернитесь к Гриану Камнегриву.", tag="Эскорт", desc="Идите за предателем Братства Справедливости до Луноречья; монстры по пути нападают на него, помогайте ему. Дойдя, вернитесь на Sentinel Hill."}, [34]={npc="Гриан Камнегрив", tgt="Гриан Камнегрив"}, [35]={npc="Неотосланное письмо", npcObj=true, desc="Щелкните правой кнопкой по предмету «Неотосланное письмо» в сумке, чтобы взять задание."}, [36]={}, [37]={text="Бронзовая трубка", npc="Билибуб Шестеренок", desc="Ограниченный товар. Покупайте, только если есть в наличии."}, [38]={npc="Барос Алекстон", tgt="Барос Алекстон"}, [39]={npc="Барос Алекстон", tgt="Барос Алекстон"}, [40]={npc="Тюремщик Телвотер", tgt="Тюремщик Телвотер"}, [41]={npc="Даториан Ралл", tgt="Даториан Ралл"}, [42]={npc="Даториан Ралл", tgt="Даториан Ралл"}, [43]={npc="Фолиант Отваги", npcObj=true, desc="Щелкните правой кнопкой по предмету «Фолиант Отваги» в сумке, чтобы взять задание."}, [44]={npc="Даториан Ралл", tgt="Даториан Ралл", desc="Щелкните правой кнопкой по предмету «Фолиант Отваги» в сумке, чтобы взять задание."}, [45]={npc="Даториан Ралл", tgt="Даториан Ралл"}, [46]={npc="Дафна Стилвелл", tgt="Дафна Стилвелл"}, [47]={npc="Дафна Стилвелл", tgt="Дафна Стилвелл", desc="Сопроводите Дафну Стилвелл. По пути будут засады Братства Справедливости."}, [48]={npc="Дафна Стилвелл", tgt="Дафна Стилвелл", desc="Сопроводите Дафну Стилвелл. По пути будут засады Братства Справедливости."}, [49]={npc="Дафна Стилвелл", tgt="Дафна Стилвелл"}, [50]={npc="Даториан Ралл", tgt="Даториан Ралл"}, [51]={npc="Даториан Ралл", tgt="Даториан Ралл"}, [52]={npc="Джордан Стилвелл", tgt="Джордан Стилвелл"}, [53]={npc="Джордан Стилвелл", tgt="Джордан Стилвелл", desc="Нужны материалы, например самоцвет Кор и партия руды Балора."}, [54]={hint="Возьмите список Джордана, добудьте немного древесины белокаменного дуба, партию очищенной руды Бэйлора, кузнечный молот Джордана и самоцвет Кора и отдайте их Джордану Стилвелл