    ["03-28"] = {steps={[2]={npc="Часовой Мелирия Ледяная Тень", tgt="Часовой Мелирия Ледяная Тень"}, [3]={npc="Иллиана", tgt="Иллиана"}, [4]={npc="Пельтур Белая Луна", tgt="Пельтур Белая Луна"}, [5]={text="Бегите по дороге до этой точки."}, [6]={text="Бегите по дороге до этой точки."}, [7]={hint="Отправляйтесь в Воющую Долину, изучите фолиант Мел'Тандрис, затем возвращайтесь к часовому Мелирии Ледяной Тени святилище Эссины.", desc="За книгой идите через пещеру. Легко сагрить лишних, а если там редкий монстр — еще сложнее."}, [8]={text="Бегите по дороге до этой точки."}, [9]={hint="Отнимите лунный камень Упавшего Неба у Чащобного Оракула и принесите его Пельтуру в Астранаар."}, [10]={text="Бегите по дороге до этой точки."}, [11]={hint="Освободите заточенные души высокорожденных на Ночной поляне и Сатирнааре, затем вернитесь к Делгрену Очистителю на заставу Мейстры."}, [12]={npc="Анилия", tgt="Анилия"}, [13]={npc="Анилия", tgt="Анилия"}, [14]={hint="Убейте Гелтариса и верните Ветвь Кенария Иллиане в святилище Эссины."}, [15]={npc="Кайнет Штиль", tgt="Кайнет Штиль"}, [16]={npc="Масейра Осенняя Луна", tgt="Масейра Осенняя Луна"}, [17]={hint="Масейра Осенняя Луна просит вас осмотреть местность к западу от Лесной Песни, где водятся демоны Сатирнаара. Принесите ей любые сведения о ее муже Куротеле."}, [18]={npc="Масейра Осенняя Луна", tgt="Масейра Осенняя Луна"}, [19]={nodeA="{a:3137}"}, [21]={npc="Пельтур Белая Луна", tgt="Пельтур Белая Луна"}, [22]={npc="Часовой Мелирия Ледяная Тень", tgt="Часовой Мелирия Ледяная Тень"}, [23]={npc="Часовой Мелирия Ледяная Тень", tgt="Часовой Мелирия Ледяная Тень", tag="Необязательно"}, [24]={npc="Иллиана", tgt="Иллиана"}, [25]={npc="Делгрен Очиститель", tgt="Делгрен Очиститель"}}},
    ["03-29"] = {steps={[1]={tag="Необязательно", desc="В Дарнасе мало опыта. Если спешите, пропустите."}, [2]={text="Пройдите через портал в Деревне Рут'теран в Дарнас.", tag="Необязательно"}, [3]={npc="Тин'тель Танец Клинка", tgt="Тин'тель Танец Клинка", tag="Необязательно"}, [4]={npc="Тин'тель Танец Клинка", tgt="Тин'тель Танец Клинка", tag="Необязательно"}, [5]={hint="Поищите в сундуке Велинды ее дневник, затем принесите его вместе с ключом Тинтэль Танцующий Клинок в Дарнасс.", tag="Необязательно"}, [6]={npc="Тин'тель Танец Клинка", tgt="Тин'тель Танец Клинка", tag="Необязательно"}, [7]={npc="Тин'тель Танец Клинка", tgt="Тин'тель Танец Клинка", tag="Необязательно"}, [8]={text="Пройдите через портал в Дарнасе обратно в Деревню Рут'теран.", tag="Необязательно"}, [9]={text="Если вы делали необязательные задания в Дарнасе, летите из Деревни Рут'теран в Кабестан (с пересадками в Аубердине и на Заставе Талрендис); если пропускали, летите из Астранаара (с пересадкой на Заставе Талрендис). Идите по главной дороге на юг, обойдите Лагерь Таурахо и спуститесь в Тысячу Игл на Большом подъемнике. Через Бастион Мор'шан идите, только если ни одна из двух точек не открыта."}, [10]={text="Бегите по дороге до этой точки."}, [11]={nodeA="{a:489}"}, [12]={npc="Виззл Медноштиф", tgt="Виззл Медноштиф"}, [13]={npc="Виззл Медноштиф", tgt="Виззл Медноштиф"}, [14]={npc="Пшикс Медноштиф", tgt="Пшикс Медноштиф"}, [15]={npc="Крейвел Углебрад", tgt="Крейвел Углебрад"}, [16]={npc="Крейвел Углебрад", tgt="Крейвел Углебрад"}, [17]={npc="Крейвел Углебрад", tgt="Крейвел Углебрад"}, [18]={npc="Поззик", tgt="Поззик"}, [19]={npc="Начальник трассы Зерин", tgt="Начальник трассы Зерин"}, [20]={hint="Добудьте 10 полых костей падальщика для Поззика с Мерцающей равнины."}, [21]={hint="Убейте 10 просоленных василисков, 10 просоленных хрусталисков и 6 просоленных взорней, после чего вернитесь к директору трассы Зерину на Мерцающую равнину."}, [22]={hint="Принесите 9 крепких черепашьих панцирей Виззлу Медноштифу на Мерцающую равнину."}, [23]={hint="Принестие 30 деталей болида Крейвелу Углебраду на Мерцающую равнину."}, [24]={hint="Принесите 6 порций соленого яда скорпида Пшиксу Медноштифу на Мерцающую равнину."}, [25]={npc="Поззик", tgt="Поззик"}, [26]={npc="Начальник трассы Зерин", tgt="Начальник трассы Зерин"}, [27]={npc="Виззл Медноштиф", tgt="Виззл Медноштиф"}, [28]={npc="Пшикс Медноштиф", tgt="Пшикс Медноштиф"}, [29]={npc="Крейвел Углебрад", tgt="Крейвел Углебрад"}, [30]={text="С Мерцающих равнин идите по дороге на юг в Танарис, откройте пункт полёта в Прибамбасске и затем используйте камень возвращения.", tag="Маршрут полёта ещё не открыт. В первый раз доберитесь туда пешком."}, [31]={nodeA="{a:976}"}, [32]={}}},
    ["03-30"] = {name="Нагорье Арати", steps={[1]={desc="Если Опорный пункт не открыт, летите в Гавань Менетилов, идите по дороге на северо-восток через Болотину, пересеките Мост Тандола в Нагорье Арати и дойдите по дороге до Опорного пункта."}, [2]={npc="Капитан Ниалс", tgt="Капитан Ниалс"}, [3]={npc="Капитан Ниалс", tgt="Капитан Ниалс", desc="Сдайте Демару Бранту в крепости Фархолд в Лесоречье; на следующем этапе вы туда придете."}, [4]={npc="Щит с надписью РОЗЫСК", npcObj=true, tag="Необязательно"}, [5]={npc="Щит с надписью РОЗЫСК", npcObj=true, tag="Необязательно"}, [6]={npc="Скуэрто", tgt="Скуэрто"}, [7]={npc="Ученик Кретьен", tgt="Ученик Кретьен"}, [8]={npc="Кристаллы Мизраэли", npcObj=true}, [9]={hint="Соберите 12 крупиц Мощи Мизраэли и принесите их к радужным осколкам в Теснине Сухоусов."}, [10]={npc="Радужные осколки", npcObj=true}, [11]={desc="Качайтесь примерно до трех четвертей 36-го уровня."}, [12]={npc="Радужные осколки", npcObj=true}, [13]={hint="Добудьте огненный ключ, резной ключ и громовой ключ с западного связывающего камня, восточного связывающего камня и внешнего связывающего камня."}, [14]={npc="Кви", tgt="Кви"}, [15]={npc="Кви", tgt="Кви"}, [16]={hint="Найдите 10 клыков троллей клана Сухокожих, 4 лекарских сумки клана Сухокожих и нож Темного охотника и принесите их ученику Кретьену в Опорном пункте.", desc="Остерегайтесь патрулирующего Отрекшегося-курьера."}, [17]={npc="Ученик Кретьен", tgt="Ученик Кретьен"}, [18]={npc="Скуэрто", tgt="Скуэрто"}, [19]={hint="Найдите заклинательный жезл Трелана и верните его Скуэрто в Опорный пункт."}, [21]={npc="Скуэрто", tgt="Скуэрто"}, [22]={npc="Скуэрто", tgt="Скуэрто", tag="Необязательно"}, [23]={hint="Убейте 10 проходимцев из Синдиката и 6 наемников Синдиката."}, [24]={npc="Капитан Ниалс", tgt="Капитан Ниалс"}, [25]={npc="Капитан Ниалс", tgt="Капитан Ниалс", tag="Необязательно"}, [26]={npc="Внутренний связывающий камень", npcObj=true}, [27]={hint="Принесите капитану Ниалс в Опорный пункт голову Марез.", ta