    ["05-d8"] = {name="Монастырь Алого Ордена", entrance="Тирисфальские леса 82.60, 33.80", pickup="Возьмите задания для подземелья заранее, по пути: Болотина (2-й заход). Возвращаться перед походом не придется.", pickupS={{"Возьмите задания для подземелья заранее, по пути: Болотина (2-й заход)"}, {"Возвращаться перед походом не придется"}}, steps={[1]={npc="Библиотекарь Мая Белокожка", tgt="Библиотекарь Мая Белокожка"}, [2]={desc="Вы сделаете пересадку в Стальгорне."}, [3]={text="От Южнобережья идите на север через Предгорья Хилсбрада и Альтеракские горы, войдите в Западные Чумные земли и идите на запад в Тирисфальские леса; по дороге дойдите до Монастыря Алого ордена в северо-восточном углу.", tag="Требуется внутриигровая проверка"}, [4]={text="Вход: Монастырь Алого Ордена"}, [5]={}, [6]={text="В Штормграде идите в Квартал Дворфов и сядьте на подземный поезд до Стальгорна."}, [7]={npc="Библиотекарь Мая Белокожка", tgt="Библиотекарь Мая Белокожка", tag="Необязательно"}}},
    ["03-31"] = {steps={[1]={desc="В крепости Фархолд еще нет точки полета, поэтому при первом визите идите от Приозерья по большой дороге на восток к западному входу в Лесоречье."}, [2]={text="За входом к востоку от Красногорья начинаются Щетинистые холмы; гноллы 36-38 уровней у входа бьют больно.", tag="Требуется внутриигровая проверка, Маршрут полёта ещё не открыт. В первый раз доберитесь туда пешком."}, [3]={npc="Разведчик Болайн", tgt="Разведчик Болайн"}, [4]={npc="Седрик Далтон", tgt="Седрик Далтон"}, [5]={npc="Седрик Далтон", tgt="Седрик Далтон"}, [6]={npc="Седрик Далтон", tgt="Седрик Далтон"}, [7]={npc="Седрик Далтон", tgt="Седрик Далтон", tag="Необязательно, Делайте с группой", desc="Снаргл - элита 40-го уровня; если не справляетесь, пропустите его."}, [8]={npc="Кудряш", tgt="Кудряш"}, [9]={npc="Халлиган Тернер", tgt="Халлиган Тернер"}, [10]={npc="Халлиган Тернер", tgt="Халлиган Тернер"}, [11]={npc="Швыряш", tgt="Швыряш"}, [12]={npc="Швыряш", tgt="Швыряш"}, [13]={hint="Отправляйтесь со Швыряшем на помощь Кудряшу.", desc="Идите за Швыряшем, чтобы спасти Кудряша."}, [14]={hint="Убейте 8 |4мистика:мистиков:мистиков;, 8 |4зверолова:звероловов:звероловов; и 6 |4громилу:громил:громил; из стаи Красногорья по просьбе Седрика Далтона в Южном дозоре."}, [15]={hint="Раздобудьте 8 |4пилу:пилы:пил; в лагерях гноллов на Щетинистых холмах для Халлигана Тернера с лесопилки.", tag="Требуется внутриигровая проверка"}, [16]={hint="Найдите и убейте Снаргла в Щетинистых холмах, после чего принесите его рыло Седрику Далтону в Южный дозор.", tag="Необязательно, Делайте с группой", desc="Снаргл - элита 40-го уровня; если не справляетесь, пропустите его."}, [17]={npc="Халлиган Тернер", tgt="Халлиган Тернер"}, [18]={npc="Халлиган Тернер", tgt="Халлиган Тернер"}, [19]={npc="Элинор Холмсби", tgt="Элинор Холмсби"}, [20]={npc="Робби Холмсби", tgt="Робби Холмсби"}, [21]={npc="Дозорный Фредерикс", tgt="Дозорный Фредерикс"}, [22]={npc="Седрик Далтон", tgt="Седрик Далтон"}, [23]={npc="Седри