    ["03-38"] = {steps={[1]={desc="Если Высота Найджела открыта, летите прямо туда (с пересадкой в Тераморе) и пропустите следующий шаг. Если Пик Каменного Когтя не открыт, летите в Астранаар и войдите в Когтистые горы через пещеру к югу от Ясеневого леса."}, [2]={text="От Пика Каменного Когтя идите по дороге на юг вниз с горы, обойдите лагерь Орды у Приюта Солнечного Камня и войдите в Пустоши с юго-запада Когтистых гор. Высота Найджела находится на севере Пустошей.", tag="Маршрут полёта ещё не открыт. В первый раз доберитесь туда пешком."}, [3]={nodeA="{a:608}"}, [4]={npc="Брат Антон", tgt="Брат Антон"}, [5]={npc="Хормиц Жужжалит", tgt="Хормиц Жужжалит"}, [6]={hint="Убейте 30 опустошителей-отрекшихся и вернитесь к брату Антону на Высоте Найджела."}, [7]={hint="Принесите 8 единиц эктоплазмы и ящик призрачных магнитов Хормицу Жужжалиту в Пустоши."}, [8]={npc="Хормиц Жужжалит", tgt="Хормиц Жужжалит"}, [9]={npc="Брат Антон", tgt="Брат Антон"}}},
    ["03-39"] = {steps={[1]={bindA="{a:35}", desc="Если камень возвращения на перезарядке, слетайте с Высоты Найджела в Кабестан (с пересадкой в Тераморе), а затем плывите на корабле в Пиратскую Бухту."}, [2]={npc="Шиззи Пуззырикс", tgt="Шиззи Пуззырикс"}, [3]={npc="Шиззи Пуззырикс", tgt="Шиззи Пуззырикс"}, [4]={npc="Диг", tgt="Диг"}, [5]={npc="Кебок", tgt="Кебок"}, [6]={npc="Командир флота Морской Рог", tgt="Командир флота Морской Рог"}, [7]={npc="Капер Блоудс", tgt="Капер Блоудс"}, [8]={npc="Морской волк Маккинли", tgt="Морской волк Маккинли"}, [9]={npc="Одноглазый Диззи", tgt="Одноглазый Диззи"}, [10]={hint="Командир флота Морской Рог попросил вас убить 10 висельников из шайки Кровавого Паруса и принести ему карты и приказы Кровавого Паруса.", desc="Ищите бутылки на пляже — подобранная бутылка начинает задание."}, [11]={hint="Диг из Пиратской бухты попросил принести ему 15 понюшек табаку."}, [12]={hint="Диззи Одноглазый из Пиратской бухты попросил вас отобрать его глаз у пиратов Кровавого Паруса."}, [13]={hint="Принесите каперу Блоудсу из Пиратской бухты 10 свертков со стеблями акириса."}, [14]={hint="Принесите барону Ревилгазу в Пиратскую бухту 6 браслетов элементалей воды.", tag="Необязательно"}, [15]={npc="Капер Блоудс", tgt="Капер Блоудс"}, [16]={npc="Капер Блоудс", tgt="Капер Блоудс"}, [17]={npc="Алкач Виски", tgt="Алкач Виски"}, [18]={npc="Диг", tgt="Диг"}, [19]={npc="Командир флота Морской Рог", tgt="Командир флота Морской Рог"}, [20]={npc="Командир флота Морской Рог", tgt="Командир флота Морской Рог"}, [21]={npc="Одноглазый Диззи", tgt="Одноглазый Диззи", desc="Недостающие страницы «Зеленых холмов Тернистой долины» купите на аукционе: 1, 4, 6, 8, 10, 11, 14, 16, 18, 20, 21, 24, 25, 26, 27."}, [23]={hint="Командир флота Морской Рог попросил вас убить капитана Штиллеца, капитана Кильвателя и командира флота Фираллона.", desc="«Загадка Кортелло» может появиться на нижней палубе любого из трех кораблей. Получив ее, щелкните правой кнопкой."}, [24]={hint="Принесите Шиззи Пуззыриксу из Пиратской бухты 12 образцов смеси Занзила."}, [25]={hint="Принесите деревянную ногу Моури, золотую подзорную трубу Джон-Джона и огромное кольцо Чаки \"Морскому волку\" Маккинли в Пиратскую бухту."}, [26]={hint="Отнесите 5 шкур кроколисков-хрустогрызов Дриззлику в Пиратскую бухту.", tag="Необязательно"}, [27]={npc="Хеминг Эрнестуэй", tgt="Хеминг Эрнестуэй"}, [28]={npc="Хеминг Эрнестуэй", tgt="Хеминг Эрнестуэй", tag="Необязательно"}, [29]={hint="Хеминг Эрнестуэй попросил вас убить Тетиса, хитрого, опасного ящера Тернистой долины.", tag="Позже, по пути, Необязательно"}, [30]={hint="Принесите Шиззи Пуззыриксу из Пиратской бухты 10 синих Поющих кристаллов."}, [31]={hint="Добудьте 18 клыков троллей из клана Дробителей Черепов и принесите их Кебоку в Бухту Контрабандистов."}, [32]={hint="Сэр С. Дж. Эрлгедин из экспедиции Эрнестуэя попросил принести ему клык Баг'тиры.", tag="Необязательно"}, [33]={npc="Хеминг Эрнестуэй", tgt="Хеминг Эрнестуэй", tag="Необязательно"}, [34]={npc="Сэр С. Дж. Эрлгедин", tgt="Сэр С. Дж. Эрлгедин", tag="Необязательно"}, [35]={npc="Хеминг Эрнестуэй", tgt="Хеминг Эрнестуэй", tag="Необязательно"}, [36]={hint="Хеминг Эрнестуэй попросил вас принести ему голову короля Бангалаша, огромного белого тигра.", tag="Позже, по пути, Необязательно"}, [37]={npc="Хеминг Эрнестуэй", tgt="Хеминг Эрнестуэй", tag="Необязательно"}, [38]={bindA="{a:35}"}, [39]={npc="Шиззи Пуззырикс", tgt="Шиззи Пуззырикс"}, [40]={npc="Шиззи Пуззырикс", tgt="Шиззи Пуззырикс"}, [41]={npc="Кебок", tgt="Кебок"}, [42]={npc="Командир флота Морской Рог", tgt="Командир флота Морской Рог"}, [43]={npc="Морской волк Маккинли", tgt="Морской волк Маккинли"}, [44]={npc="Дриззлик", tgt="Дриззлик", tag="Необязательно"}, [45]={npc="Барон Ревилгаз", tgt="Барон Ревилгаз", tag="Необязательно"}, [48]={npc="Капер Грой", tgt="Капер Грой"}, [49]={npc="Табета", tgt="Табета"}, [50]={npc="Табета", tgt="Табета"}, [51]={hint="Принесите сферу Подземного огня Табете из Пылевых топей."}, [52]