    ["04-45"] = {steps={[1]={npc="Сигрун Рудотес", tgt="Сигрун Рудотес", tag="Необязательно", desc="По пути обычно выпадают «Чары яркого пламени». Если не выпали, бросьте задание."}, [2]={npc="Гарек", tgt="Гарек", tag="Делайте с группой, Необязательно", desc="Нужно убить двух черных драконов 50 уровня (элиты); без группы пропустите."}, [3]={hint="С помощью знака Земли активируйте алмазный, опаловый и аметистовый столпы и извлеките рунные камни.", tag="Позже, по пути, Делайте с группой, Необязательно"}, [4]={npc="Печать Земли", npcObj=true, tag="Делайте с группой, Необязательно"}, [5]={npc="Печать Земли", npcObj=true, tag="Делайте с группой, Необязательно"}, [6]={npc="Гарек", tgt="Гарек", tag="Делайте с группой, Необязательно"}, [7]={npc="Сигрун Рудотес", tgt="Сигрун Рудотес", tag="Необязательно"}, [8]={hint="Убейте посла Инфернуса в Крепости Ангор и принесите доказательство его смерти советнику Белграму в Стальгорн."}, [9]={text="Из Бесплодных земель идите на запад и по горной тропе рядом с лагерем Орды Каргат войдите в Тлеющее ущелье. Обходите Каргат стороной.", tag="Маршрут полёта ещё не открыт. В первый раз доберитесь туда пешком."}, [10]={npc="Деревянная уборная", npcObj=true}, [11]={hint="Убейте 8 геологов из клана Черного Железа и принесите 15 отрезов шелка тому, кто заперт в отхожем месте в Тлеющем ущелье."}, [12]={text="Убейте Маргола Яростеня — за него много опыта.", tag="Необязательно", desc="Рог Маргола открывает цепочку заданий о ключе от Тлеющего ущелья; если вы ее не берете, пропустите шаги 13, 32-33, 35, 37 и 40-42, а на шаге 43 летите из Стальгорна обратно в Лагерь Братства Тория."}, [13]={npc="Рог Маргола", npcObj=true, tag="Необязательно", desc="Щелкните правой кнопкой по предмету «Рог Маргола» в сумке, чтобы взять задание."}, [14]={npc="Деревянная уборная", npcObj=true}, [15]={npc="Деревянная уборная", npcObj=true}, [16]={hint="Возьмите учетную книгу Кринкеля Сталлинна и найдите все перечисленные в ней вещи. Затем отнесите их и книгу Кринкелю Сталлинну в Танарис."}, [17]={npc="Дориус Камнестраж", tgt="Дориус Камнестраж"}, [18]={npc="Опаленное письмо", npcObj=true}, [19]={npc="Опаленное письмо", npcObj=true}, [20]={npc="Каларан Ветрорез", tgt="Каларан Ветрорез"}, [21]={npc="Каларан Ветрорез", tgt="Каларан Ветрорез"}, [22]={npc="Каларан Ветрорез", tgt="Каларан Ветрорез"}, [23]={nodeA="{a:1446}"}, [24]={npc="Розыск/Пропал без вести/Найден", npcObj=true, tag="Делайте с группой, Необязательно", desc="Надсмотрщик Мальтор — элита 50 уровня; без группы пропустите."}, [25]={npc="Розыск/Пропал без вести/Найден", npcObj=true}, [26]={npc="Розыск/Пропал без вести/Найден", npcObj=true}, [27]={npc="Хансел Большерук", tgt="Хансел Большерук"}, [28]={npc="Хансел Большерук", tgt="Хансел Большерук", tag="Необязательно"}, [29]={npc="Хансел Большерук", tgt="Хансел Большерук"}, [30]={npc="Мастер-кузнец Гориврат", tgt="Мастер-кузнец Гориврат"}, [31]={bindA="{a:144}"}, [32]={npc="Горный пехотинец Щебеночка", tgt="Горный пехотинец Щебеночка", tag="Необязательно"}, [33]={npc="Горный пехотинец Щебеночка", tgt="Горный пехотинец Щебеночка", tag="Необязательно"}, [35]={npc="Куратор Ториус", tgt="Куратор Ториус", tag="Необязательно"}, [36]={npc="Куратор Ториус", tgt="Куратор Ториус"}, [37]={npc="Куратор Ториус", tgt="Куратор Ториус", tag="Необязательно"}, [38]={npc="Куратор Ториус", tgt="Куратор Ториус"}, [39]={npc="Советник Белграм", tgt="Советник Белграм"}, [40]={tag="Необязательно", desc="Возвращайтесь к Горный пехотинец Щебеночка за ключом, только если у вас есть Доказательство смотрителя (Наконец-то!); иначе перейдите к шагу 43."}, [41]={npc="Горный пехотинец Щебеночка", tgt="Горный пехотинец Щебеночка", tag="Необязательно"}, [42]={text="Откройте только что полученным ключом от Тлеющего ущелья ворота рядом с горцем Пебблбитти и пройдите через туннель в Тлеющее ущелье.", tag="Необязательно"}, [43]={tag="Необязательно", desc="Если у вас нет ключа от Тлеющего ущелья, летите из Стальгорна прямо в Тлеющее ущелье. Если вы уже прошли через туннель, пропустите это."}, [44]={hint="Принесите 4 сердца пламени и 4 меры масла големов Велароку Ветрорезу."}, [45]={npc="Каларан Ветрорез", tgt="Каларан Ветрорез"}, [46]={npc="Каларан Ветрорез", tgt="Каларан Ветрорез"}, [47]={hint="Найдите и верните фурму и подзорную трубу наблюдателя надсмотрщику Скренджу в Тлеющем ущелье. Единственная известная информация: вещи были украдены дворфами Черного Железа. Подзорная труба является бесценным прибором для наблюдения, а фурма - незаменимым кузнечным инструментом."}, [48]={hint="Убейте 15 надсмотрщиков и 15 поработителей из клана Черного Железа. По выполнении задания вернитесь к десятнику Скренджу в Тлеющее ущелье."}, [49]={hint="По поручению Хансела Большерука убейте 20 тяжелых боевых големов, которых можно найти в землях, окружающих Котел в Тлеющем ущелье. По выполнении задания вернитесь к Ханселу."}, [50]={hint="По указанию Хансела Большерука убейте 20 |4опаляющего лавового паука:опаляющих лавовых пауков:опаляющих лавовых пауков; в Тлеющем ущелье. Пауки водятся на вулканических плато и в озерах лавы в Тлеющем ущелье.", tag="Необязательно", desc="Отдельный крюк, других целей рядом нет. Если торопитесь, пропустите."}, [51]={hint="По поручению Хансела Большерука убейте 20 пламезавров, обитающих в озерах лавы в Шлаковой Яме - это часть Котла в Тлеющем ущелье."}, [53]={hint="Дворф Черного Железа, вероломный надзиратель Мальториус, скрывается в глубине Шлаковой Ямы в Котле, что в Тлеющем ущелье.", tag="Позже, по пути, Делайте с группой, Необязательно"}, [54]={hint="Верните секретные документы по изготовлению огненного плавня, украденные надзирателем Мальториусом. Инспектор скорее всего находится в Шлаковой Яме в Котле. Документы верните мастеру-кузнецу Гориврату в Тлеющем ущелье."}, [55]={hint="Принесите 8 окованных торием кинжалов Велароку Ветрорезу."}, [56]={npc="Умирающий археолог", tgt="Умирающий археолог"}, [57]={npc="Умирающий археолог", tgt="Умирающий археолог", tag="Необязательно"}, [58]={npc="Каларан Ветрорез", tgt="Каларан Ветрорез"}, [59]={npc="Каларан Ветрорез", tgt="Каларан Ветрорез"}, [60]={hint="Найдите таинственный артефакт, охраняемый идолослужителями Сумеречного Молота в северо-западной области Тлеющего ущелья.", tag="Позже, по пути"}, [61]={hint="Найдите знак Рагнароса и принесите его Велароку Ветрорезу.", tag="Позже, по пути"}, [62]={npc="Зимаель Лунный Репей", tgt="Зимаель Лунный Репей", tag="Необязательно"}, [63]={npc="Зимаель Лунный Репей", tgt="Зимаель Лунный Репей", tag="Необязательно"}, [64]={npc="Зимаель Лунный Репей", tgt="Зимаель Лунный Репей", tag="Необязательно"}, [65]={npc="Капитан дозорных Лоло Долгобой", tgt="Капитан дозорных Лоло Долгобой", tag="Делайте с группой, Необязательно"}, [66]={npc="Хансел Большерук", tgt="Хансел Большерук"}, [67]={npc="Хансел Большерук", tgt="Хансел Большерук", tag="Необязательно"}, [68]={npc="Хансел Большерук", tgt="Хансел Большерук"}, [69]={npc="Надсмотрщик Скрендж", tgt="Надсмотрщик Скрендж"}, [70]={npc="Надсмотрщик Скрендж", tgt="Надсмотрщик Скрендж"}, [71]={npc="Мастер-кузнец Гориврат", tgt="Мастер-кузнец Гориврат"}, [72]={npc="Каларан Ветрорез", tgt="Каларан Ветрорез", tag="Необязательно"}, [73]={npc="Каларан Ветрорез", tgt="Каларан Ветрорез"}, [74]={npc="Каларан Ветрорез", tgt="Каларан Ветрорез"}, [75]={npc="Каларан Ветрорез", tgt="Каларан Ветрорез"}, [76]={npc="Факел воздаяния", npcObj=true}, [77]={npc="Каларан Ветрорез", tgt="Каларан Ветрорез"}, [78]={npc="Оруженосец Малтрейк", tgt="Оруженосец Малтрейк"}, [79]={npc="Оруженосец Малтрейк", tgt="Оруженосец Малтрейк"}, [80]={hint="Подожгите северную, южную, восточную и западную сторожевые башни с помощью факела воздаяния."}, [81]={npc="Алтарь Сунтары", npcObj=true}, [82]={npc="Умирающий археолог", tgt="Умирающий археолог"}, [83]={hint="Убейте Латорика Черного и Обсидиона и принесите голову Латорика и сердце Обсидиона Ториусу в Стальгорн."}, [84]={npc="Оруженосец Малтрейк", tgt="Оруженосец Малтрейк"}, [85]={npc="Сокровищница черных драконов", npcObj=true}, [86]={npc="Сокровищница черных драконов", npcObj=true}, [87]={text="Бегите по дороге до этой точки."}, [88]={text="Прыгните в лаву и умрите: одно задание можно взять только в виде духа."}, [89]={text="Бегите к своему телу и воскресните."}, [90]={tag="Необязательно, Делайте с группой", desc="Качайтесь здесь до 52 только с группой в Глубины Черной горы. В одиночку пропустите."}, [91]={desc="Если камень возвращения готов, вернитесь им в Телсамар и летите оттуда; если нет, вернитесь на Ториевую заставу (37.90, 30.40) и найдите распорядителя полётов."}, [92]={npc="Куратор Ториус", tgt="Куратор Ториус"}, [93]={npc="Старший исследователь Магеллас", tgt="Старший исследователь Магеллас"}, [94]={npc="Историк Карник", tgt="Историк Карник"}, [95]={npc="Историк Карник", tgt="Историк Карник"}, [96]={text="Привяжите камень возвращения в таверне Стальгорна (18.60, 51.60).", bind="Стальгорн"}, [97]={desc="Если Крепость Стражей Пустоты не открыта, летите в Темнолесье, идите на восток через Перевал Мертвого Ветра в Болото Печали, а затем на юг через Выжженные земли до Крепости Стражей Пустоты."}, [98]={npc="Тадиус Мрачная Тень", tgt="Тадиус Мрачная Тень"}, [99]={npc="Загадка Кортелло", npcObj=true, desc="Щелкните правой кнопкой по предмету «Загадка Кортелло» в сумке, чтобы взять задание. Можно взять только с 50-го уровня."}, [100]={text="От крепости Сторожевая Преграда идите на север из Выжженных земель в Болото Печали и по дороге на запад до западной части болота."}, [101]={npc="Промокший свиток", npcObj=true}, [102]={npc="Промокший свиток", npcObj=true}}},
    ["05-d11"] = {name="Глубины Черной Горы", entrance="Тлеющее ущелье 34.80, 85.30", steps={[1]={desc="В Болоте Печали нет пункта полёта Альянса: идите на запад через Перевал Мертвого Ветра обратно в Темнолесье и летите оттуда."}, [2]={text="От Лагеря Братства Тория идите на юг через Тлеющее ущелье и войдите в Черную гору на юге."}, [3]={npc="Франклорн Искусник", tgt="Франклорн Искусник"}, [4]={npc="Франклорн Искусник", tgt="Франклорн Искусник"}, [5]={npc="Франклорн Искусник", tgt="Франклорн Искусник"}, [6]={text="Вход: Глубины Черной Горы"}, [7]={hint="Убейте Точеня Темностроя и добудьте великий молот, Железный Друг. Отнесите Железного Друга в святилище Тауриссана и вложите его в руки статуи Франклорна Искусника."}, [8]={npc="Монумент Франклорну Искуснику", npcObj=true}, [9]={desc="Выйдите из Черной горы на север через Тлеющее ущелье, вернитесь в Лагерь Братства Тория и летите оттуда."}}},
    ["04-46"] = {steps={[1]={desc="В Болоте Печали нет пункта полёта Альянса: идите на запад через Перевал Мертвого Ветра обратно в Темнолесье и летите оттуда."}, [2]={npc="Шиззи Пуззырикс", tgt="Шиззи Пуззырикс"}, [3]={npc="Шиззи Пуззырикс", tgt="Шиззи Пуззырикс"}, [4]={npc="Алкач Виски", tgt="Алкач Виски"}, [5]={npc="Морской волк Маккинли", tgt="Морской волк Маккинли"}, [6]={npc="Фин Горемык", tgt="Фин Горемык", tag="Необязательно"}, [7]={npc="Карлс Пропеллерз", tgt="Карлс Пропеллерз"}, [8]={npc="Карлс Пропеллерз", tgt="Карлс Пропеллерз"}, [9]={npc="Карлс Пропеллерз", tgt="Карлс Пропеллерз"}, [10]={npc="Карлс Пропеллерз", tgt="Карлс Пропеллерз"}, [11]={npc="Карлс Пропеллерз", tgt="Карлс Пропеллерз"}, [12]={tag="Необязательно"}, [13]={npc="Бережно свернутая записка", npcObj=true, desc="Щелкните правой кнопкой по предмету «Бережно свернутая записка» в сумке, чтобы взять задание. Щелкните правой кнопкой по сложенной записке, полученной ранее, чтобы начать задание."}, [14]={npc="Принцесса Пуба", tgt="Принцесса Пуба"}, [15]={npc="Принцесса Пуба", tgt="Принцесса Пуба", tag="Необязательно"}, [16]={hint="Убейте Короля Муклу, возвращайтесь с ключом к принцессе Пубе и освободите ее.", tag="Позже, по пути"}, [17]={npc="Принцесса Пуба", tgt="Принцесса Пуба", tag="Необязательно"}, [19]={hint="Верните Гекельберри Шмотту из Пиратской бухты его сундук.", tag="Позже, по пути"}, [20]={hint="Найдите знахаря Унбагва и попросите его вызвать Мокка Дикаря. Принесите сердце Мокка Фину Горемыку.", tag="Позже, по пути"}, [21]={tag="Необязательно"}, [22]={npc="Фин Горемык", tgt="Фин Горемык", tag="Необязательно"}, [24]={hint="Заберите круглый камень из мастерской Марвона Клепальщика в Кабестане."}, [26]={npc="Заплесневелый свиток", npcObj=true}, [27]={npc="Заплесневелый свиток", npcObj=true}}},
    ["04-47"] = {steps={[1]={desc="Свиток лежит в пещере ящеров к юго-западу от Пылевых топей. Сначала идите на восток обратно в Терамор (67.48, 51.30), а потом летите."}, [2]={npc="Кринкель Сталлер", tgt="Кринкель Сталлер"}, [3]={npc="Поливалка", tgt="Поливалка"}, [4]={npc="Поливалка", tgt="Поливалка"}, [5]={npc="Синь Гогельмогель", tgt="Синь Гогельмогель"}, [6]={npc="Синь Гогельмогель", tgt="Синь Гогельмогель"}, [7]={npc="Синь Гогельмогель", tgt="Синь Гогельмогель"}, [8]={text="От Прибамбасска идите по дороге на север на Мерцающую равнину в Тысячу Игл."}, [9]={npc="Крейвел Углебрад", tgt="Крейвел Углебрад"}, [10]={npc="Крейвел Углебрад", tgt="Крейвел Углебрад"}, [11]={npc="Начальник гномского гаража", tgt="Начальник гномского гаража"}, [12]={npc="Марвон Клепальщик", tgt="Марвон Клепальщик"}, [13]={npc="Пьедестал Ульдума", npcObj=true, tag="Необязательно"}, [14]={npc="Каменный дозорный Нограннона", tgt="Каменный дозорный Нограннона"}, [15]={npc="Пьедестал Ульдума", npcObj=true}, [16]={npc="Пьедестал Ульдума", npcObj=true, tag="Необязательно"}, [17]={text="Бегите по дороге до этой точки."}}},
    ["04-48"] = {steps={[1]={text="По горной дороге к западу от Танариса спуститесь по спуску в Кратер Ун'Горо. Землепроходец Торва стоит прямо у входа внизу спуска.", tag="Маршрут полёта ещё не открыт. В первый раз доберитесь туда пешком."}, [2]={npc="Землепроходец Торва", tgt="Землепроходец Торва"}, [3]={npc="Землепроходец Торва", tgt="Землепроходец Торва"}, [4]={npc="Разбитый плот", npcObj=true, desc="Соберите по 7 красных, синих, зеленых и желтых кристаллов и добудьте у ящеров «Изорванный дневник»."}, [5]={npc="Небольшая сумка", npcObj=true}, [6]={npc="Небольшая сумка", npcObj=true}, [7]={hint="Найдите последнюю добычу Лар'корви, украдите кусок трупа жесткозуба и вернитесь к землепроходцу Торве в Кратер Ун'Горо."}, [8]={desc="Бейте растения около 67.7, 30.7 до середины 49-го уровня."}, [9]={npc="Землепроходец Торва", tgt="Землепроходец Торва"}, [10]={npc="Землепроходец Торва", tgt="Землепроходец Торва"}, [11]={hint="Принесите 2 феромонные железы равазавра землепроходцу Торве в преддверие Кратера Ун'Горо."}, [12]={npc="Землепроходец Торва", tgt="Землепроходец Торва"}, [13]={npc="Землепроходец Торва", tgt="Землепроходец Торва"}, [14]={hint="С помощью предметов из мешочка Торвы выманите Лар'корви и сразите его. Принесите голову Лар'корви землепроходцу Торве ко входу в Кратер Ун'Горо.", tag="Необязательно", desc="Это задание сложнее. Можно оставить до возвращения в Ун'Горо."}, [15]={npc="Карна Сомнамбулер", tgt="Карна Сомнамбулер"}, [16]={npc="Линкен", tgt="Линкен"}, [17]={npc="Линкен", tgt="Линкен"}, [18]={nodeA="{a:541}"}, [19]={npc="Виллиден Маршал", tgt="Виллиден Маршал"}, [20]={npc="Холания Маршал", tgt="Холания Маршал"}, [21]={npc="Искр Пустокоп", tgt="Искр Пустокоп"}, [22]={npc="Джей Ди Колли", tgt="Джей Ди Колли"}, [23]={npc="Джей Ди Колли", tgt="Джей Ди Колли"}, [24]={npc="Джей Ди Колли", tgt="Джей Ди Колли"}, [25]={npc="Джей Ди Колли", tgt="Джей Ди Колли"}, [26]={npc="Джей Ди Колли", tgt="Джей Ди Колли"}, [27]={npc="Опасайся жутедактиля", npcObj=true}, [28]={npc="Майджин", tgt="Майджин"}, [29]={npc="Шиззл", tgt="Шиззл"}, [30]={hint="Отыщите Северный хрустальный пилон в Кратере Ун'Горо."}, [31]={hint="Принесите 2 шкуры Ун'Горской гориллы, 2 шкуры Ун'Горского топтуна и 2 шкуры Ун'Горского рокотуна землепроходцу Торве к входу в Кратер Ун'Горо."}, [33]={hint="Принесите ящик с провизией и исследовательское оборудование Виллидену Маршалу в Кратер Ун'Горо."}, [34]={hint="Отыщите Восточный хрустальный пилон в Кратере Ун'Горо."}, [35]={npc="Землепроходец Торва", tgt="Землепроходец Торва"}, [36]={npc="Землепроходец Торва", tgt="Землепроходец Торва"}, [37]={text="Бегите по дороге до этой точки."}, [38]={text="Бегите по дороге до этой точки."}, [39]={hint="Воспользуйтесь фиалом для образцов, чтобы взять образец материала стены улья из одного из инкубаторов Гориши в Кратере Ун'Горо. Ищите в ульях комнаты со свисающими гроздьями личинок."}, [40]={hint="Отыщите Западный хрустальный пилон."}, [41]={text="Завершите взятые задания на убийство и сбор."}, [42]={hint="Принесите 8 чешуй перепончатого деметродона 8 чешуй перепончатого жутедактиля Шиззлу в Укрытие Маршалла."}, [43]={hint="Соберите 15 кровоцветов и принесите их Майджину."}, [44]={hint="Убейте 10 жутедактилей и 15 бесноватых жутедактилей, затем поговорите со Мучей Кусора в Укрытии Маршалла."}, [45]={npc="Шиззл", tgt="Шиззл"}, [46]={npc="Майджин", tgt="Майджин"}, [47]={npc="Майджин", tgt="Майджин"}, [48]={npc="Муча Кусора", tgt="Муча Кусора"}, [49]={npc="Искр Пустокоп", tgt="Искр Пустокоп"}, [50]={npc="Холания Маршал", tgt="Холания Маршал"}, [51]={npc="Виллиден Маршал", tgt="Виллиден Маршал"}, [52]={npc="Изорванный дневник", npcObj=true, tag="Необязательно", desc="Берите задание правым щелчком, только если с монстров выпал Изорванный дневник."}, [53]={npc="Виллиден Маршал", tgt="Виллиден Маршал", tag="Необязательно"}, [54]={npc="Джей Ди Колли", tgt="Джей Ди Колли"}, [55]={npc="Джей Ди Колли", tgt="Джей Ди Колли"}, [56]={npc="Джей Ди Колли", tgt="Джей Ди Колли"}, [57]={npc="Джей Ди Колли", tgt="Джей Ди Колли"}, [58]={npc="Джей Ди Колли", tgt="Джей Ди Колли"}, [60]={bind="Стальгорн", desc="Если камень возвращения на перезарядке, летите из Укрытия Маршалла в Аубердин (с пересадками в Прибамбасске и Тераморе) и пропустите следующие два шага."}, [62]={desc="Этот корабль по пути заходит в Южнобережье. Сойдите в Аубердине."}, [64]={npc="Эрелас Янтарное Небо", tgt="Эрелас Янтарное Небо"}, [65]={npc="Дарин Добрый Ветер", tgt="Дарин Добрый Ветер"}, [66]={npc="Дарин Добрый Ветер", tgt="Дарин Добрый Ветер"}, [67]={text="Пройдите через портал в Деревне Рут'теран в Дарнас."}, [68]={npc="Грацина Сила Духа", tgt="Грацина Сила Духа"}, [69]={npc="Грацина Сила Духа", tgt="Грацина Сила Духа"}, [70]={npc="Астария Ловец Звезд", tgt="Астария Ловец Звезд", tag="Необязательно"}, [71]={text="Пройдите через портал в Дарнасе обратно в Деревню Рут'теран."}, [73]={text="Привяжите камень возвращения в таверне Астранаар (37.00, 49.20).", bindA="{a:415}"}, [74]={npc="Магинор Дюма", tgt="Магинор Дюма", tag="Необязательно", desc="Вводное задание в Штормграде можно пропустить. По прибытии в Азшару все равно нужно сначала найти Санат Лим-Йо, чтобы вас телепортировали на утес."}, [75]={npc="Санат Лим-Йо", tgt="Санат Лим-Йо", tag="Необязательно", desc="Сдавайте здесь, только если брали вводное задание."}, [76]={text="Поговорите с Санат Лим-Йо и попросите телепортировать вас на утес к верховному магу Ксилему."}, [77]={npc="Верховный маг Ксилем", tgt="Верховный маг Ксилем"}, [78]={hint="Принесите 10 горстей сияющей пыли верховному магу Ксилему."}, [79]={npc="Верховный маг Ксилем", tgt="Верховный маг Ксилем", desc="Пыль лежит у подножия горы; вернитесь к Санат Лим-Йо тем же способом, чтобы вас телепортировали наверх."}, [80]={npc="Верховный маг Ксилем", tgt="Верховный маг Ксилем"}, [81]={hint="Соберите 6 заколдованных кораллов и принесите их верховному магу Ксилему."}, [82]={npc="Верховный маг Ксилем", tgt="Верховный маг Ксилем"}, [83]={npc="Верховный маг Ксилем", tgt="Верховный маг Ксилем", desc="Морфаз находится в Храме Атал'Хаккара."}, [84]={hint="Добудьте кристалл тайной магии из брюха Морфаза и принесите его верховному магу Ксилему.", desc="Морфаз находится в Храме Атал'Хаккара."}, [85]={npc="Верховный маг Ксилем", tgt="Верховный маг Ксилем", desc="Морфаз находится в Храме Атал'Хаккара. Чтобы спуститься с утеса, используйте камень возвращения или поищите вариант телепортации рядом с Ксилемом (нужна проверка в игре)."}, [86]={npc="Брат Джошуа", tgt="Брат Джошуа", desc="Возьмите в Штормграде и сдайте Огтинку в Азшаре."}, [87]={npc="Огтинк", tgt="Огтинк", desc="Возьмите в Штормграде и сдайте Огтинку в Азшаре."}, [88]={npc="Огтинк", tgt="Огтинк"}, [89]={hint="Добудьте 4 железы здорового мохоногого оленя и принесите их Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата."}, [90]={npc="Огтинк", tgt="Огтинк"}, [91]={npc="Огтинк", tgt="Огтинк"}, [92]={hint="Принесите лимфу нежити Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата."}, [93]={npc="Огтинк", tgt="Огтинк"}, [94]={npc="Огтинк", tgt="Огтинк", desc="Морфаз находится в Храме Атал'Хаккара."}, [95]={hint="Убейте Морфаза в затонувшем храме Атал'Хаккара и принесите его кровь Грете Замшелому Копыту в Оскверненный лес. Вход в храм сокрыт на болоте Печали.", desc="Морфаз находится в Храме Атал'Хаккара."}, [96]={npc="Грета Замшелое Копыто", tgt="Грета Замшелое Копыто", desc="Морфаз находится в Храме Атал'Хаккара."}, [97]={npc="Дорион", tgt="Дорион", desc="Возьмите в Дарнасе (или Стальгорне, Штормграде) и сдайте Огтинку в Азшаре."}, [98]={npc="Огтинк", tgt="Огтинк", desc="Возьмите в Дарнасе (или Стальгорне, Штормграде) и сдайте Огтинку в Азшаре."}, [99]={npc="Огтинк", tgt="Огтинк"}, [100]={hint="Принесите пару великолепных рогов мохоногого оленя Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата."}, [101]={npc="Огтинк", tgt="Огтинк"}, [102]={npc="Огтинк", tgt="Огтинк"}, [103]={hint="Принесите 6 чешуй волношлепа Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата."}, [104]={npc="Огтинк", tgt="Огтинк"}, [105]={npc="Огтинк", tgt="Огтинк", desc="Зеленый дракон находится в Храме Атал'Хаккара."}, [106]={hint="Принесите зуб Морфаза Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.", desc="Зеленый дракон находится в Храме Атал'Хаккара."}, [107]={npc="Огтинк", tgt="Огтинк", desc="Зеленый дракон находится в Храме Атал'Хаккара."}}},
    ["04-49"] = {steps={[1]={text="От Астранаара идите по дороге на север в Оскверненный лес.", tag="Маршрут полёта ещё не открыт. В первый раз доберитесь туда пешком."}, [2]={npc="Аратандис Серебряное Небо", tgt="Аратандис Серебряное Небо"}, [3]={npc="Гразл", tgt="Гразл"}, [4]={npc="Грета Замшелое Копыто", tgt="Грета Замшелое Копыто"}, [5]={npc="Эридана Грусть Ветра", tgt="Эридана Грусть Ветра"}, [6]={npc="Тарун Красное Перо", tgt="Тарун Красное Перо", tag="Необязательно"}, [7]={hint="Гразл желает, чтобы вы заслужили доверие. Вам нужно убить 6 воинов, 6 землепроходцев и 6 садовников из племени Мертвого Леса. Выполнив поручение, возвращайтесь в южную часть Оскверненного леса к Изумрудному святилищу."}, [8]={npc="Гразл", tgt="Гразл"}, [9]={npc="Гразл", tgt="Гразл"}, [10]={hint="Убейте 11 скверноподданных, 9 тенеловов, 9 разбойников из племени Нефритового Пламени и Ксаватраса. Возвращайтесь к Эридане Грусти Ветра в Оскверненный лес по выполнении задания."}, [11]={hint="Отправляйтесь в Джеденар и убейте 4 джеденарских гончих, 4 джеденарских стражей, 6 джеденарских адептов и 6 джеденарских сектантов, затем возвращайтесь к Грете Заиндевевшее Копыто в Оскверненный лес."}, [12]={npc="Эридана Грусть Ветра", tgt="Эридана Грусть Ветра"}, [13]={npc="Эридана Грусть Ветра", tgt="Эридана Грусть Ветра"}, [14]={npc="Грета Замшелое Копыто", tgt="Грета Замшелое Копыто"}, [15]={npc="Грета Замшелое Копыто", tgt="Грета Замшелое Копыто"}, [16]={hint="Возьмите пустую флягу и наполните ее водой из лунного колодца, что находится в центре Джеденара. Возвращайтесь к Грете Замшелому Копыту в Оскверненный лес."}, [17]={desc="Убивайте монстров около 35, 59 в Джеденаре."}, [18]={hint="Найдите и уничтожьте 2 энтропических зверей и 2 энтропических ужасов при обследовании долины Рваных Ран. После проверьте, по-прежнему ли заполнены кратеры оскверненной водой. Затем возвращайтесь к Таруну Красному Перу в Оскверненный лес.", tag="Необязательно", desc="Отдельный крюк, других целей рядом нет. Если торопитесь, пропустите."}, [19]={hint="Эридана Грусть Ветра из Оскверненного леса просит вас убить 8 призывателей огня, 8 предателей и 8 плутов из племени Нефритового огня, а также Ксаварика. По выполнении задания возвращайтесь к Эридане."}, [20]={npc="Флейта Ксаварика", npcObj=true, desc="Щелкните правой кнопкой по предмету «Флейта Ксаварика» в сумке, чтобы взять задание."}, [21]={hint="Принесите флейту Ксаварика и 5 образцов уз Скверны нефритового огня Эридане Грусти Ветра в южную часть Оскверненного леса."}, [22]={hint="Принесите 15 кровавых янтарей Аратандис Серебряному Небу в Оскверненный лес."}, [23]={nodeA="{a:1998}"}, [24]={npc="Нафиэн", tgt="Нафиэн"}, [25]={npc="Нафиэн", tgt="Нафиэн", tag="Требуется внутриигровая проверка"}, [26]={hint="Нафиэн просит вас убить 6 дозорных, 6 мстителей и 6 шаманов из племени Мертвого Леса. По выполнении возвращайтесь на север Оскверненного леса ко входу в крепость Древобрюхов.", tag="Требуется внутриигровая проверка"}, [27]={npc="Нафиэн", tgt="Нафиэн", tag="Требуется внутриигровая проверка"}, [28]={text="Бегите по дороге до этой точки.", desc="Войдите здесь в пещеру Крепости Древобрюхов и пройдите её насквозь — это Зимние Ключи."}, [29]={node="Лунная поляна", tag="Требуется внутриигровая проверка", desc="В пещере Крепости Древобрюхов есть ответвление в Лунной поляне; сначала зайдите туда и откройте пункт полета, затем вернитесь в пещеру и идите в Зимние Ключи. Для части на Хиджале позже вы полетите в Лунную поляну."}, [30]={npc="Сальфа", tgt="Сальфа", tag="Требуется внутриигровая проверка"}, [31]={npc="Донова Снегонора", tgt="Донова Снегонора"}, [32]={npc="Донова Снегонора", tgt="Донова Снегонора"}, [33]={npc="Мегги Молот-Шмолот", tgt="Мегги Молот-Шмолот"}, [34]={npc="Джессика Редпат", tgt="Джессика Редпат"}, [35]={nodeA="{a:2255}"}, [36]={npc="Ниби Всемогущий", tgt="Ниби Всемогущий"}, [37]={npc="Бесенок", tgt="Бесенок"}, [38]={npc="Бесенок", tgt="Бесенок"}, [39]={hint="Принесите отрез ткани Скверны Бесенку в Оскверненный лес."}, [40]={npc="Бесенок", tgt="Бесенок"}, [41]={npc="Бесенок", tgt="Бесенок"}, [42]={hint="Принесите 10 кусков гнилой древесины и 4 порции экстракта ядовитой крови Бесенку в Оскверненный лес."}, [43]={npc="Бесенок", tgt="Бесенок"}, [44]={npc="Бесенок", tgt="Бесенок"}, [45]={hint="Принесите 6 вудуистских перьев троллей из затонувшего храма."}, [46]={npc="Бесенок", tgt="Бесенок"}, [47]={npc="Бесенок", tgt="Бесенок"}, [48]={hint="Бесенок из Оскверненного леса просит вас принести ему три порции безупречной субстанции скверны из трех различных мест."}, [49]={npc="Бесенок", tgt="Бесенок"}, [50]={npc="Бесенок", tgt="Бесенок", desc="Крошиус находится на севере Оскверненного леса. Нужна группа."}, [51]={hint="Обыщите долину Рваных Ран в Оскверненном лесу и найдите останки Крошиуса. Когда вы их найдете, поднесите к ним пламень Скверны и подождать, пока Крошиус не восстанет из праха. Когда инфернал очнется, убейте его и возьмите из его тела огненное ядро Крошиуса.", desc="Крошиус находится на севере Оскверненного леса. Нужна группа."}, [52]={npc="Ниби Всемогущий", tgt="Ниби Всемогущий", desc="Крошиус находится на севере Оскверненного леса. Нужна группа."}}},
    ["04-50"] = {steps={[2]={npc="Пратт Макгруббен", tgt="Пратт Макгруббен"}, [3]={npc="Трояс Лунный Бриз", tgt="Трояс Лунный Бриз"}, [4]={npc="Трояс Лунный Бриз", tgt="Трояс Лунный Бриз"}, [5]={npc="Греган Пивоплюй", tgt="Греган Пивоплюй"}, [6]={npc="Камнедробитель", tgt="Камнедробитель"}, [7]={hint="Найдите Грегана Пивоплюя на севере Фераласа. Выясните у него, как получить эликсир Видере, и вернитесь к Донове Снегоноре."}, [8]={hint="Зарядите посох Трояса и отыщите Монолит Равноденствия.", desc="Дальше можно запрыгнуть наверх и срезать путь."}, [9]={npc="Шая Листогон", tgt="Шая Листогон"}, [10]={npc="Монолит Равноденствия", npcObj=true, desc="Используйте посох из сумки."}, [11]={npc="Монолит Равноденствия", npcObj=true}, [12]={hint="Принесите 10 шкур йети из пещеры Бешеного оврага Пратту Макгруббену в Крепость Оперенной Луны в Фераласе."}, [13]={npc="Нетронутая шкура йети", npcObj=true, tag="Необязательно", desc="Если с йети выпадет «Нетронутая шкура йети», щелкните по ней правой кнопкой."}, [14]={npc="Пратт Макгруббен", tgt="Пратт Макгруббен"}, [15]={npc="Пратт Макгруббен", tgt="Пратт Макгруббен", tag="Необязательно"}, [16]={npc="Трояс Лунный Бриз", tgt="Трояс Лунный Бриз"}}},
    ["04-51"] = {steps={[1]={bindA="{a:415}", desc="Если камень возвращения на перезарядке, летите из Крепости Оперенной Луны в Астранаар (с пересадкой в Аубердине), а затем идите на север в Оскверненный лес."}, [2]={npc="Аратандис Серебряное Небо", tgt="Аратандис Серебряное Небо"}, [3]={npc="Грета Замшелое Копыто", tgt="Грета Замшелое Копыто"}, [4]={npc="Грета Замшелое Копыто", tgt="Грета Замшелое Копыто"}, [5]={npc="Эридана Грусть Ветра", tgt="Эридана Грусть Ветра"}, [6]={npc="Эридана Грусть Ветра", tgt="Эридана Грусть Ветра"}, [7]={npc="Эридана Грусть Ветра", tgt="Эридана Грусть Ветра"}, [8]={npc="Тарун Красное Перо", tgt="Тарун Красное Перо"}, [9]={npc="Донова Снегонора", tgt="Донова Снегонора", desc="Вернитесь в Астранаар, летите на Поляну Когтистых Ветвей, а затем идите на север через Крепость Древобрюхов в Зимние Ключи."}, [10]={npc="Донова Снегонора", tgt="Донова Снегонора"}, [11]={npc="Донова Снегонора", tgt="Донова Снегонора"}, [12]={npc="Донова Снегонора", tgt="Донова Снегонора"}, [13]={desc="Убивайте фурболгов около 32, 36 в лагере Зимней Спячки."}, [14]={npc="Грегор Грейстоун", tgt="Грегор Грейстоун"}, [15]={npc="Грегор Грейстоун", tgt="Грегор Грейстоун"}, [16]={desc="Вы сделаете пересадку на Заставе Талрендис."}, [17]={npc="Лив Быстрочин", tgt="Лив Быстрочин"}, [18]={npc="Ислен Заклинатель Воды", tgt="Ислен Заклинатель Воды"}, [19]={npc="Ислен Заклинатель Воды", tgt="Ислен Заклинатель Воды"}, [21]={npc="Алхимик Пестычинс", tgt="Алхимик Пестычинс"}, [22]={text="Выпив эликсир Видере, не воскресайте: найдите NPC задания в виде духа."}, [23]={npc="Гаэриан", tgt="Гаэриан"}, [24]={npc="Гаэриан", tgt="Гаэриан"}, [25]={text="Вернитесь к телу и воскресните."}, [26]={npc="Подозрительное надгробие", npcObj=true}, [27]={npc="Подозрительное надгробие", npcObj=true}, [28]={npc="Тран'рек", tgt="Тран'рек"}, [29]={npc="Алхимик Пестычинс", tgt="Алхимик Пестычинс"}}},
    ["04-52"] = {name="Кратер Ун'Горо", steps={[2]={npc="Линкен", tgt="Линкен"}, [3]={npc="Линкен", tgt="Линкен"}, [4]={npc="Джей Ди Колли", tgt="Джей Ди Колли"}, [5]={npc="Джей Ди Колли", tgt="Джей Ди Колли"}, [6]={npc="Муча Кусора", tgt="Муча Кусора"}, [7]={npc="Холания Маршал", tgt="Холания Маршал", tag="Необязательно"}, [8]={hint="Отнесите 12 образцов сверхлипкой смолы Тран'реку в Прибамбасск."}, [9]={npc="Кракл", tgt="Кракл"}, [10]={hint="Добудьте 9 образцов пепла Ун'Горо из элементалей огня, что водятся вокруг вулкана в Кратере Ун'Горо, и доставьте их Лив Быстрочин в Кабестан."}, [11]={hint="Выясните, где находится точка самой высокой температуры на Вулкане Огненного Венца, по просьбе Кракла из Кратера Ун'Горо."}, [12]={hint="Принесите ароматическую железу Гориши и 5 образцов почвы из Кратера Ун'Горо алхимику Пестычинсу в Прибамбасск.", tag="Необязательно", desc="Отдельный крюк, других целей рядом нет. Если торопитесь, пропустите."}, [13]={npc="Землепроходец Торва", tgt="Землепроходец Торва"}, [14]={npc="Кракл", tgt="Кракл"}, [15]={npc="Кракл", tgt="Кракл"}, [16]={npc="Ринго", tgt="Ринго", desc="Задание на сопровождение: в группе берите, когда у всех одинаковый прогресс, и отключите автопринятие."}, [17]={npc="Ринго", tgt="Ринго"}, [18]={hint="Отведите Ринго к Муче Кусора в Укрытие Маршалла.", tag="Эскорт", desc="Приведите Ринго обратно в Укрытие Маршалла. Он потеряет сознание по пути; когда это случится, используйте на нем флягу Спрэггл."}, [19]={npc="Муча Кусора", tgt="Муча Кусора"}, [20]={npc="Чи-Та 3", tgt="Чи-Та 3"}, [21]={npc="Чи-Та 3", tgt="Чи-Та 3"}, [22]={hint="Найдите мифриловую обшивку и вернитесь к Чи-Та 3 в Кратер Ун'Горо.", desc="Купите мифриловый корпус заранее на аукционе или попросите инженера его сделать."}, [23]={npc="Чи-Та 3", tgt="Чи-Та 3"}, [24]={hint="Принесите шкуру Учи землепроходцу Торве ко входу в Кратер Ун'Горо."}, [25]={npc="Чи-Та 3", tgt="Чи-Та 3"}, [26]={hint="Доставьте Чи-Та 3 назад Карне Сомнамбулер в Кратер Ун'Горо.", tag="Эскорт", desc="Сопроводите Чи-Та 3 обратно к Карна Сомнамбулер; монстры по пути нападают на него, защищайте его."}, [27]={npc="Карна Сомнамбулер", tgt="Карна Сомнамбулер"}, [28]={npc="Землепроходец Торва", tgt="Землепроходец Торва"}, [29]={text="Рядом с Торвой нет точки полета: выйдите из кратера Ун'Горо по пандусу позади него в Танарис и бегите на северо-восток в Прибамбасск."}, [30]={npc="Тран'рек", tgt="Тран'рек"}, [31]={npc="Алхимик Пестычинс", tgt="Алхимик Пестычинс", tag="Необязательно"}, [32]={desc="Вы сделаете пересадку в Тераморе."}, [33]={npc="Лив Быстрочин", tgt="Лив Быстрочин"}, [34]={bindA="{a:415}"}, [36]={text="В таверне Аубердина привяжите камень возвращения (Хозяйка таверны Шосси) (37.04, 44.13).", bind="Аубердин"}, [38]={npc="Эрелас Янтарное Небо", tgt="Эрелас Янтарное Небо"}, [39]={text="Пройдите через портал в Деревне Рут'теран в Дарнас."}, [40]={hint="Отправляйтесь в Дарнасс и наберите в фиал Эриданы благословенной воды из храма Луны. Возвращайтесь к Эридане с полным фиалом."}, [41]={text="Пройдите через портал в Дарнасе обратно в Деревню Рут'теран."}, [43]={npc="Грета Замшелое Копыто", tgt="Грета Замшелое Копыто"}, [44]={npc="Грета Замшелое Копыто", tgt="Грета Замшелое Копыто", tag="Необязательно"}, [45]={npc="Эридана Грусть Ветра", tgt="Эридана Грусть Ветра"}, [46]={npc="Эридана Грусть Ветра", tgt="Эридана Грусть Ветра"}, [47]={npc="Эридана Грусть Ветра", tgt="Эридана Грусть Ветра"}, [48]={npc="Эридана Грусть Ветра", tgt="Эридана Грусть Ветра"}, [49]={npc="Эридана Грусть Ветра", tgt="Эридана Грусть Ветра"}, [50]={hint="Добудьте 11 серебристых когтей и 1 сердце Железнолесья для Эриданы Грусти Ветра.", tag="Необязательно", desc="Отдельный крюк, других целей рядом нет. Если торопитесь, пропустите."}, [51]={npc="Эридана Грусть Ветра", tgt="Эридана Грусть Ветра", tag="Необязательно"}, [52]={bind="Аубердин", desc="Если он на перезарядке, вернитесь пешком в Астранаар и летите в Аубердин."}, [53]={desc="Этот корабль по пути заходит в Южнобережье. Сойдите