    ["04-54"] = {steps={[1]={text="Если Дозор Моргана открыт, летите туда прямо из Стальгорна. Если нет, летите в Приозерье и идите по дороге на север в Пылающие степи; Дозор Моргана находится прямо у входа.", tag="Маршрут полёта ещё не открыт. В первый раз доберитесь туда пешком."}, [2]={nodeA="{a:2418}"}, [3]={npc="Орелиус", tgt="Орелиус"}, [4]={npc="Орелиус", tgt="Орелиус"}, [5]={npc="Хелендис Речной Мыс", tgt="Хелендис Речной Мыс", tag="Необязательно"}, [6]={npc="Тинки Кипеллер", tgt="Тинки Кипеллер"}, [7]={npc="Максворт Суперблеск", tgt="Максворт Суперблеск"}, [8]={hint="Пойдите в руины Тауриссана в Пылающих степях и добудьте информацию из таурисанских реликвий. Вернитесь к королевскому историку Аркессону."}, [9]={hint="Принесите переписанный с таблички текст Максворту Суперблеску в Пылающие степи."}, [10]={hint="Убейте 15 огров-магов, 7 огров и 7 громил из клана Огненного Чрева. По выполнении задания вернитесь к Орелиусу."}, [11]={hint="Принесите 8 сущностей детенышей драконов и Драко-инкарцинатор 900 Тинки Кипеллер в Пламенеющий Стяг в Пылающих степях."}, [12]={hint="Убейте 15 детенышей черного дракона, 10 черных драконидов, 4 черных драконид и 1 черного дракона. По выполнении задания вернитесь к Хелендису Речному Мысу.", tag="Позже, по пути"}, [13]={npc="Цирус Раскаиватель", tgt="Цирус Раскаиватель", tag="Необязательно"}, [14]={npc="Цирус Раскаиватель", tgt="Цирус Раскаиватель", tag="Необязательно"}, [15]={npc="Тинки Кипеллер", tgt="Тинки Кипеллер"}, [16]={npc="Максворт Суперблеск", tgt="Максворт Суперблеск"}, [17]={npc="Орелиус", tgt="Орелиус"}, [18]={npc="Орелиус", tgt="Орелиус", tag="Необязательно"}, [19]={npc="Хелендис Речной Мыс", tgt="Хелендис Речной Мыс", tag="Необязательно"}, [20]={npc="Хелендис Речной Мыс", tgt="Хелендис Речной Мыс", tag="Необязательно"}, [21]={hint="Найдите Гор'теша на западе от скалы Молота Ужаса. Убейте Гор'теша и отнесите его голову Орелиусу в Пылающие степи.", tag="Необязательно"}, [22]={hint="Орелиусу нужны 50 медальонов Черно