"}, [43]={npc="Мулгрис Глубокая Река", tgt="Мулгрис Глубокая Река"}, [44]={text="Бегите по дороге до этой точки."}, [45]={text="Привяжите камень возвращения в таверне Aerie Peak (13.80, 41.60).", bindA="{a:348}"}, [46]={npc="Сокровище Кортелло", npcObj=true}, [47]={npc="Командир Ашлам Отважный Кулак", tgt="Командир Ашлам Отважный Кулак"}, [48]={npc="Командир Ашлам Отважный Кулак", tgt="Командир Ашлам Отважный Кулак"}, [49]={hint="Принесите 20 камней Плети приспешников верховному жрецу Тель'данису в Западные Чумные земли."}, [50]={npc="Верховный жрец Тель'данис", tgt="Верховный жрец Тель'данис"}, [51]={npc="Верховный жрец Тель'данис", tgt="Верховный жрец Тель'данис"}, [52]={npc="Командир Ашлам Отважный Кулак", tgt="Командир Ашлам Отважный Кулак"}, [53]={npc="Командир Ашлам Отважный Кулак", tgt="Командир Ашлам Отважный Кулак", desc="Сдайте задание, чтобы получить Камень мощи."}, [54]={hint="Принесите вудуистские перья Ашламу Отважному Кулаку.", desc="Сдайте задание, чтобы получить Камень мощи."}, [55]={npc="Командир Ашлам Отважный Кулак", tgt="Командир Ашлам Отважный Кулак", desc="Сдайте задание, чтобы получить Камень мощи."}, [56]={bindA="{a:348}"}}},
    ["04-56"] = {steps={[1]={text="От Заоблачного пика идите по горной тропе на север в Западные Чумные земли, затем на восток через реку Тондрорил в Восточные Чумные земли. Тирион Фордринг находится в хижине прямо у входа."}, [2]={npc="Тирион Фордринг", tgt="Тирион Фордринг"}, [3]={npc="Тирион Фордринг", tgt="Тирион Фордринг"}, [4]={npc="Тирион Фордринг", tgt="Тирион Фордринг"}, [5]={hint="Убейте 20 карликовых чумных псов, 5 чумных псов и 5 бесноватых чумных псов. По выполнении задания вернитесь к Тириону Фордрингу."}, [6]={hint="Убейте 30 чумных нетопырей и вернитесь к Тириону Фордрингу."}, [7]={hint="Найдите личинок-падальщиков и падальщиков-пожирателей. Убейте побольше и наберите из мяса. Возвращайтесь к Тириону Фордрингу, когда накопите 15 кусков мяса червей-трупоедов."}, [8]={npc="Памела Редпат", tgt="Памела Редпат"}, [9]={npc="Памела Редпат", tgt="Памела Редпат"}, [10]={hint="Найдите куклу Памелы.", desc="В разрушенных домах Дарроушира соберите голову, левую и правую половины и соедините их правым щелчком."}, [11]={npc="Памела Редпат", tgt="Памела Редпат"}, [12]={npc="Памела Редпат", tgt="Памела Редпат"}, [13]={npc="Памела Редпат", tgt="Памела Редпат"}, [14]={npc="Герцог Николас Зверенхофф", tgt="Герцог Николас Зверенхофф"}, [15]={node="Часовня Последней Надежды"}, [16]={npc="Карлин Редпат", tgt="Карлин Редпат"}, [17]={npc="Карлин Редпат", tgt="Карлин Редпат", tag="Необязательно"}, [18]={npc="Управляющий Ален", tgt="Управляющий Ален"}, [19]={hint="Освободите 15 духов Дарроушира и возвращайтесь к Карлину Редпату.", tag="Необязательно", desc="Отдельный крюк, других целей рядом нет. Если торопитесь, пропустите."}, [20]={npc="Тирион Фордринг", tgt="Тирион Фордринг"}, [21]={npc="Тирион Фордринг", tgt="Тирион Фордринг"}, [22]={npc="Тирион Фордринг", tgt="Тирион Фордринг"}, [23]={npc="Тирион Фордринг", tgt="Тирион Фордринг"}, [24]={npc="Тирион Фордринг", tgt="Тирион Фордринг"}, [25]={npc="Тирион Фордринг", tgt="Тирион Фордринг"}, [26]={hint="Отправляйтесь в Крипту - в самой южной части Восточных Чумных земель - и добудьте молот Таэлана. Отнесите его Тириону Фордрингу."}, [27]={hint="Принесите голову Зельдарра Управляющему Алену в Часовню Последней Надежды."}, [28]={npc="Разорванный свиток", npcObj=true}, [29]={hint="Поищите в Восточных Чумных землях сведения про некоего Гнилостеня и пропавших агентов ШРУ. Если удастся найти знаки отличия ШРУ, отнесите их Флинту Тенемору в Лагерь Промозглого Ветра.", tag="Необязательно"}, [30]={npc="Тирион Фордринг", tgt="Тирион Фордринг"}, [31]={npc="Тирион Фордринг", tgt="Тирион Фордринг"}, [32]={npc="Управляющий Ален", tgt="Управляющий Ален"}, [33]={npc="Карлин Редпат", tgt="Карлин Редпат", tag="Необязательно"}}},
    ["04-53"] = {steps={[1]={desc="Вы сделаете пересадку в лагере Промозглого Ветра или на Заоблачном пике; если Южнобережья нет на карте полётов, летите в Штормград, как обычно, и плывите в Аубердин с порта."}, [2]={desc="Прямо в порту Южнобережья есть корабль в Аубердин — это быстрее, чем лететь в Штормград и пересаживаться. Если вы летите в Штормград, садитесь на корабль в порту Штормграда."}, [4]={hint="По просьбе Доновы Снегоноры из Зимних Ключей убейте 8 землепроходцев, 8 дозорных и 8 тотемистов из племени Зимней Спячки."}, [5]={hint="Сальфа хочет, чтобы вы убили 8 |4шамана:шаманов:шаманов; из племени Зимней Спячки, 8 |4дозорного:дозорных:дозорных; из племени Зимней Спячки и 8 |4ведмедя:ведмедей:ведмедей; из племени Зимней Спячки. Сальфа находится у входа в крепость Древобрюхов в Зимних Ключах.", tag="Требуется внутриигровая проверка"}, [6]={npc="Пустая фляга из-под огненной воды", npcObj=true, desc="Щелкните правой кнопкой по предмету «Пустая фляга из-под огненной воды» в сумке, чтобы взять задание."}, [7]={npc="Донова Снегонора", tgt="Донова Снегонора"}, [8]={npc="Донова Снегонора", tgt="Донова Снегонора"}, [9]={npc="Донова Снегонора", tgt="Донова Снегонора"}, [10]={npc="Донова Снегонора", tgt="Донова Снегонора"}, [11]={npc="Донова Снегонора", tgt="Донова Снегонора", desc="Исследование Теснина Зловещего Шепота засчитается по пути на Хиджал на следующей остановке; сдайте задание до возвращения в Зимних Ключах и перелета в Лунной поляне. Сдайте до возвращения в Зимних Ключах и перелета в Лунной поляне."}, [12]={hint="Соберите в Зимних Ключах 10 светолунных перьев, принести их Эреласу Янтарному Небу в деревню Рут'теран."}, [13]={npc="Сальфа", tgt="Сальфа", tag="Требуется внутриигровая проверка"}, [14]={npc="Котел Мертвого Леса", npcObj=true}, [15]={npc="Котел Мертвого Леса", npcObj=true}, [16]={desc="От Котла Мертвого Леса идите на юг к точке полета на Поляне Когтистых Ветвей (62.49, 24.24) и вылетайте оттуда; пересадка будет в Аубердине."}, [17]={npc="Эрелас Янтарное Небо", tgt="Эрелас Янтарное Небо"}, [18]={npc="Эрелас Янтарное Небо", tgt="Эрелас Янтарное Небо"}, [19]={npc="Дарин Добрый Ветер", tgt="Дарин Добрый Ветер"}, [21]={npc="Харло Торгуместец", tgt="Харло Торгуместец"}, [22]={npc="Вунд Ночной Охотник", tgt="Вунд Ночной Охотник"}, [23]={npc="Вунд Ночной Охотник", tgt="Вунд Ночной Охотник"}, [24]={npc="Джерон Гранильщик", tgt="Джерон Гранильщик"}, [25]={npc="Джерон Гранильщик", tgt="Джерон Гранильщик"}, [26]={npc="Джерон Гранильщик", tgt="Джерон Гранильщик"}, [27]={npc="Джерон Гранильщик", tgt="Джерон Гранильщик"}, [28]={hint="Используйте кирку Джерона, чтобы добыть фрагменты реликвии высокорожденных, Принесите их Авроре Зову Небес в Восточные Чумные земли."}, [29]={npc="Донова Снегонора", tgt="Донова Снегонора"}, [30]={npc="Поврежденный ящик", npcObj=true}, [31]={npc="Поврежденный ящик", npcObj=true}, [32]={npc="Фургон Джерона", npcObj=true}, [33]={npc="Фургон Джерона", npcObj=true}, [34]={hint="Подберите припасы Джерона из снега, и найдите дикого совуха, похитившего амулет, о котором говорил Джерон."}, [35]={npc="Раншалла", tgt="Раншалла"}, [36]={npc="Раншалла", tgt="Раншалла"}, [37]={hint="Защитите Раншаллу, пока она пытается активировать алтарь Элуны. Сообщите о ваших находках Эреласу Янтарному Небу в деревне Рут'теран."}}},
    ["04-57"] = {danger={[1]="Ghansurok (химера 61 уровня, элита) патрулирует от оскверненного гибискуса до мастерской Кайлаэны (около x55-62,5, y61,5-72,2); смотрите, где он, когда бьете кусты и возвращаетесь в мастерскую.", [2]="Горький Селаструс (элита 57 уровня) бродит у оскверненного гибискуса; будьте осторожны, когда бьете кусты.", [3]="Куча костей призывает слизь 58 уровня (элита); без группы не щелкайте по ней второй раз."}, grind={[1]={note="Северная часть Шрама Демонической Крови; все задания Felflick выполняются здесь."}}, supply={[1]={}}, steps={[1]={text="От Раншалла идите на юг в Теснину Зловещего Шепота и по ущелью на запад до конца, чтобы войти на Хиджал. У входа стоит элитный ледяной великан, а внутри — элитные демоны; держитесь дороги и не останавливайтесь.", tag="Маршрут полёта ещё не открыт. В первый раз доберитесь туда пешком., Требуется внутриигровая проверка"}, [2]={hint="Последуйте указаниям Доновы Снегоноры, а затем вернитесь к ней.", tag="Требуется внутриигровая проверка", desc="Засчитывается при проходе через ущелье на Хиджале, отдельного крюка не нужно. Достаточно, чтобы журнал заданий показывал ее как выполненную."}, [3]={text="Войдите на Хиджал в юго-восточном углу и идите по дороге на запад.", tag="Требуется внутриигровая проверка"}, [4]={npc="Quintus Wainworth", tgt="Quintus Wainworth"}, [5]={npc="Quintus Wainworth", tgt="Quintus Wainworth"}, [6]={npc="Loose Cog", npcObj=true, desc="Шестеренка на земле у дороги; щелкните правой кнопкой, чтобы подобрать ее и взять задание."}, [7]={npc="Ketharas", tgt="Ketharas", tag="Необязательно"}, [8]={npc="Ketharas", tgt="Ketharas"}, [9]={npc="Ketharas", tgt="Ketharas"}, [10]={npc="Ketharas", tgt="Ketharas"}, [11]={npc="Ketharas", tgt="Ketharas"}, [12]={npc="Ketharas", tgt="Ketharas"}, [13]={hint="Rescue 12 Hyjal Owl Eggs and bring them to Ketharas."}, [14]={hint="Collect 10 Untainted Seeds for Ketharas."}, [15]={npc="Ketharas", tgt="Ketharas"}, [16]={npc="Ketharas", tgt="Ketharas"}, [17]={npc="Ketharas", tgt="Ketharas"}, [18]={npc="Ketharas", tgt="Ketharas"}, [19]={hint="Добыча с: Hyjal Stag, Predatory Hyjal Stag"}, [20]={hint="Plant the Enchanted Seeds near the Ruined Ballista, the Ruined Catapult, and the Ruined Flying Machine.", tag="Требуется внутриигровая проверка", desc="Обломки баллисты, катапульты и летательного аппарата считаются отдельными целями, засеять нужно все три."}, [21]={npc="Ketharas", tgt="Ketharas"}, [22]={npc="Ketharas", tgt="Ketharas"}, [23]={npc="Ketharas", tgt="Ketharas"}, [24]={hint="Bury the remains at Ketharas' shrine.", tag="Требуется внутриигровая проверка", desc="Координаты — примерное расположение по сообщениям игроков."}, [25]={npc="Ketharas", tgt="Ketharas"}, [26]={npc="Ketharas", tgt="Ketharas"}, [27]={nodeA="{a:16853}", desc="Идите по дороге на запад; пункт полета находится рядом с заставой древних."}, [28]={npc="Fraxinus", tgt="Fraxinus"}, [29]={npc="Hyacinth", tgt="Hyacinth"}, [30]={npc="Hyacinth", tgt="Hyacinth"}, [31]={npc="Thylaen", tgt="Thylaen", tag="Делайте с группой, Необязательно", desc="Цель — элита 57 уровня; если в одиночку не победить, не берите."}, [32]={hint="Collect 6 samples of Untainted Soil from around the foothills of Mount Hyjal."}, [33]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [34]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [35]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", desc="Когда позже будете в Круговзоре, найдите Nami за деталями."}, [36]={hint="Убить: Tainted Shrubbery", desc="С тех же кустов гибискуса выпадают и кровоостанавливающие листья; бейте их сразу для обоих заданий. Сдайте в мастерской, когда доставите ящик."}, [37]={hint="Добыча с: Tainted Shrubbery"}, [38]={hint="Добыча с: Celastrus the Bitter", tag="Делайте с группой, Необязательно"}, [39]={npc="Hyacinth", tgt="Hyacinth"}, [40]={npc="Hyacinth", tgt="Hyacinth"}, [41]={npc="Thylaen", tgt="Thylaen", tag="Делайте с группой, Необязательно"}, [42]={npc="Hyacinth", tgt="Hyacinth"}, [43]={hint="Убить: Fraxinus"}, [44]={npc="Fraxinus", tgt="Fraxinus"}, [45]={npc="Fraxinus", tgt="Fraxinus", tag="Делайте с группой, Необязательно", desc="Цель — Сандербарк, древний 56 уровня (элита); делайте, когда есть группа. Без группы пропустите шаги \"The Dying Ancients\", \"The Dying Ancients\", \"The Dying Ancients\"."}, [46]={npc="Fraxinus", tgt="Fraxinus"}, [47]={npc="Curious Crow", tgt="Curious Crow"}, [48]={npc="Curious Crow", tgt="Curious Crow"}, [49]={npc="Curious Crow", tgt="Curious Crow"}, [50]={npc="Felflick", tgt="Felflick"}, [51]={npc="Felflick", tgt="Felflick"}, [52]={hint="Убить: Ashen Acolyte", desc="Записки падают с тех же служителей, так что выполняйте оба задания сразу."}, [53]={hint="Добыча с: Ashen Acolyte"}, [54]={npc="Felflick", tgt="Felflick"}, [55]={npc="Felflick", tgt="Felflick"}, [56]={hint="Gather 8 Fel-Slime Crystals and 1 Pristine Fel-Slime Crystal."}, [57]={npc="Felflick", tgt="Felflick"}, [58]={npc="Felflick", tgt="Felflick"}, [59]={npc="Felflick", tgt="Felflick"}, [60]={hint="Добыча с: Tyaeha Darkoath, Dazka Shadowsleep, Frezzlie Popwhiz"}, [61]={hint="Убить: Brashann Grimdark"}, [62]={npc="Felflick", tgt="Felflick"}, [63]={npc="Felflick", tgt="Felflick"}, [64]={npc="Felflick", tgt="Felflick"}, [65]={npc="Bone Pile", npcObj=true, desc="Бросьте кости чернокнижника в кучу костей рядом с лужей слизи."}, [66]={npc="Bone Pile", npcObj=true, tag="Делайте с группой, Необязательно", desc="Призывает слизь 58 уровня (элита). Без группы пропустите шаги \"Amalgamated Marrow\"-\"Amalgamated Marrow\", \"Amalgamated Marrow\"-\"A Revenge Now Bitter\", \"A Revenge Now Bitter\"."}, [67]={hint="Убить: Awakened Fel Ash Slime", tag="Делайте с группой, Необязательно"}, [68]={npc="Velician", tgt="Velician"}, [69]={npc="Felflick", tgt="Felflick", tag="Делайте с группой, Необязательно"}, [70]={npc="Felflick", tgt="Felflick", tag="Делайте с группой, Необязательно"}, [71]={npc="Curious Crow", tgt="Curious Crow"}, [72]={npc="Curious Crow", tgt="Curious Crow"}, [73]={npc="Curious Crow", tgt="Curious Crow", tag="Делайте с группой, Необязательно"}, [74]={npc="Curious Crow", tgt="Curious Crow"}, [75]={npc="Curious Crow", tgt="Curious Crow"}, [76]={npc="Curious Crow", tgt="Curious Crow"}, [77]={hint="Добыча с: Пагубная слизь"}, [78]={hint="Collect 10 Prickly Pinecones under healthy trees."}, [79]={npc="Curious Crow", tgt="Curious Crow"}, [80]={npc="Curious Crow", tgt="Curious Crow"}, [81]={npc="Curious Crow", tgt="Curious Crow"}, [82]={hint="Use the pinecones to destroy the Ashen Reign workstations.", tag="Требуется внутриигровая проверка"}, [83]={npc="Curious Crow", tgt="Curious Crow"}, [84]={npc="Curious Crow", tgt="Curious Crow", desc="Сдайте в Elderwild на западе на следующей остановке."}, [85]={hint="Hunt down and destroy the corrupted ancient Sunderbark, then plant a seed in his remains.", tag="Делайте с группой, Необязательно", desc="По пути назад на восток к Пещере отшельника."}, [86]={npc="Ketharas", tgt="Ketharas"}, [87]={npc="Ketharas", tgt="Ketharas"}, [88]={npc="Fraxinus", tgt="Fraxinus", tag="Делайте с группой, Необязательно"}, [90]={npc="Nami", tgt="Nami", desc="Следующий ящик ограничен по времени; возьмите его после возвращения из Лунной поляны."}, [91]={npc="Джерон Гранильщик", tgt="Джерон Гранильщик", desc="От Круговзора пройдите по дороге немного на запад до Starfall Village."}, [92]={text="Скачите от Starfall Village по дороге на юго-запад к горячему источнику и найдите Donova.", tag="Требуется внутриигровая проверка"}, [93]={npc="Донова Снегонора", tgt="Донова Снегонора"}, [94]={desc="Скачите от горячего источника обратно к пункту полета Круговзор и летите (пункт полета Лунная поляна открыт на остановке 49). Если репутация у Древобрюхов уже нейтральная, скачите от источника на север ко входу в Крепость Древобрюхов (27.70, 34.50); через пещеру к выходу в Лунной поляне ближе; если пункт полета Лунная поляна не открыт, идите этим же путем и по прибытии сначала откройте его (48.10, 67.34); при репутации ниже нейтральной вас атакуют. Друиды могут сразу использовать «Телепортация: Лунная поляна»; по прибытии идите к обычному пункту полета (48.10, 67.34) и откройте его, чтобы вернуться по воздуху. Если пункт полета Лунная поляна не открыт, идите этим же путем и по прибытии сначала откройте его (48.10, 67.34). При репутации ниже нейтральной вас атакуют. Друиды могут сразу использовать «Телепортация: Лунная поляна»; по прибытии идите к обычному пункту полета (48.10, 67.34) и откройте его, чтобы вернуться по воздуху."}, [95]={npc="Дендрит Блеск Звезд", tgt="Дендрит Блеск Звезд"}, [96]={npc="Дендрит Блеск Звезд", tgt="Дендрит Блеск Звезд"}, [97]={npc="Орокай", tgt="Орокай"}, [98]={npc="Орокай", tgt="Орокай"}, [99]={hint="Speak with Orokai when you are ready to see what he learned from the Faintly Glowing Branch."}, [100]={npc="Дендрит Блеск Звезд", tgt="Дендрит Блеск Звезд"}, [101]={npc="Дендрит Блеск Звезд", tgt="Дендрит Блеск Звезд"}, [102]={desc="Вылетите из обычного пункта полета Лунная поляна (48.10, 67.34) и сойдите в Круговзор, чтобы забрать ящик."}, [103]={npc="Nami", tgt="Nami", desc="Батареи в ящике выходят из строя примерно через два часа, поэтому доставьте его Кайлаэне прямо от пункта полета."}, [104]={desc="От пункта полета скачите прямо на север к мастерской Кайлаэны и сначала доставьте ящик."}}},
    ["04-58"] = {danger={[1]="Ghansurok (химера 61 уровня, элита) патрулирует к востоку от Shrine of Aviana; будьте осторожны, когда бьете гарпий."}, supply={[1]={}, [2]={}}, steps={[1]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", desc="От пункта полета скачите прямо на север к мастерской и сначала доставьте ящик."}, [2]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [3]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", desc="Материалы лежат в остатках лагеря Орды в Dae'gun на севере; подберите их, когда будете проходить позже."}, [4]={npc="Ketharas", tgt="Ketharas", desc="Скачите от мастерской на юго-восток обратно к Пещере отшельника."}, [5]={npc="Ketharas", tgt="Ketharas"}, [6]={npc="Ketharas", tgt="Ketharas"}, [7]={npc="Skylord Omnuron", tgt="Skylord Omnuron", desc="Скачите от Пещеры отшельника на северо-запад к Shrine of Aviana."}, [8]={npc="Skylord Omnuron", tgt="Skylord Omnuron"}, [9]={npc="Skylord Omnuron", tgt="Skylord Omnuron"}, [10]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [11]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [12]={hint="Добыча с: Wormwing Harpy, Wormwing Windwitch, Wormwing Ambusher"}, [13]={hint="Collect 8 Tarnished Highfeather Bangles from Wormwing Harpy nests."}, [14]={hint="Find the Jewel of the Horizon in the Wormwing harpy nests on Mount Hyjal and bring it to Ketharas."}, [15]={hint="Добыча с: Zarrat Wormwing"}, [16]={npc="Corrupted Growth", npcObj=true, desc="Щелкните правой кнопкой по оскверненному наросту на дереве, чтобы взять задание."}, [17]={hint="Использовать/собрать: Corrupted Growth", tag="Требуется внутриигровая проверка"}, [18]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [19]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [20]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [21]={npc="Skylord Omnuron", tgt="Skylord Omnuron"}, [22]={npc="Curious Crow", tgt="Curious Crow"}, [23]={npc="Curious Crow", tgt="Curious Crow", desc="Выполнить можно